/// Look up the ABI of a runtime helper.  Returns `Abi::Cell` for
/// unknown names — user-defined functions and Op stubs default to the
/// post-P199.A cell ABI.
#[must_use]
pub fn abi_of(name: &str) -> Abi {
    CODEGEN_RUNTIME_FNS
        .iter()
        .find(|f| f.name == name)
        .map_or(Abi::Cell, |f| f.abi)
}

/// True if `name` is a runtime helper defined in this module.  Used by
/// `output_function` to skip stub generation (the real implementation
/// is imported via `use loft::codegen_runtime::*`).
#[must_use]
pub fn is_codegen_runtime_fn(name: &str) -> bool {
    CODEGEN_RUNTIME_FNS.iter().any(|f| f.name == name)
}

/// Convert a DbRef to a loft_ffi::LoftRef for passing to native C-ABI functions.
/// Both types have identical layout (u16 + u32 + u32).
#[must_use]
pub fn to_loft_ref(db: DbRef) -> loft_ffi::LoftRef {
    loft_ffi::LoftRef {
        store_nr: db.store_nr,
        rec: db.rec,
        pos: db.pos,
    }
}

/// Convert a `loft_ffi::LoftRef` returned from a cdylib call into a
/// `DbRef` in the indirect (header → data) layout that loft uses
/// internally.  Mirrors `extensions::push_loft_ref` but takes
/// `&mut Stores` directly instead of going through the dispatch
/// state — used by generated native code that calls cdylib
/// functions returning store-allocated vectors/structs.
///
/// @PLAN12 phase 3.5a (2026-05-24).
#[must_use]
pub fn from_loft_ref(stores: &mut Stores, r: loft_ffi::LoftRef) -> DbRef {
    if r.is_null() {
        return DbRef {
            store_nr: 0,
            rec: 0,
            pos: 0,
        };
    }
    let base = DbRef {
        store_nr: r.store_nr,
        rec: 0,
        pos: 0,
    };
    let header = stores.claim(&base, 1);
    stores.store_mut(&base).set_u32_raw(header.rec, 4, r.rec);
    DbRef {
        store_nr: r.store_nr,
        rec: header.rec,
        pos: 4,
    }
}
