/// Allocate a database root record for the given type.
/// The generated code calls this as `OpDatabase(stores, var, tp)` where `var` is
/// passed by value (`DbRef`).  The function allocates into the store referenced by
/// `db`, then returns the updated `DbRef`.
/// Bytecode equivalent: `OpDatabase` in `src/state/io.rs:319`.
pub fn OpDatabase(cell: &std::cell::UnsafeCell<Stores>, mut db: DbRef, db_tp: i32) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let db_tp = db_tp as u16;
    // B2-runtime parity with the bytecode VM (`state/io.rs::database`): an
    // EnumValue record must be large enough for the parent enum's LARGEST
    // variant, and `Stores::claim` takes WORDS — word 0 holds the size header
    // + type tag, the payload's `size` BYTES start at byte 8.
    let size = stores.enum_parent_size(db_tp);
    // The native twin of the bytecode VM's `LOFT_TRACE_DB` line (`state/io.rs`).
    // Without it the switch went quiet the moment a call crossed into a package's
    // shared library — which is where the slot-adoption it exists to show lives.
    if crate::keys::trace_db() {
        crate::loft_eprintln!(
            "[db] native OpDatabase db_tp={db_tp} ({}) db=#{}@{},{} size={size}",
            stores.types[db_tp as usize].name,
            db.store_nr,
            db.rec,
            db.pos,
        );
    }
    if db.store_nr == u16::MAX {
        // Null sentinel (no real store yet) — allocate a fresh one.
        db = stores.null();
    }
    stores.clear(&db);
    let r = stores.claim(&db, 1 + u32::from(size).div_ceil(8));
    // P259 commit 3 — record the type allocated into this store so
    // free_named can recognise closure-record stores at free time
    // (cascade-free walks `__closure_*` records' DbRef fields).
    stores.allocations[r.store_nr as usize].set_known_type(db_tp);
    stores.store_mut(&r).set_u32_raw(r.rec, 4, u32::from(db_tp));
    stores.set_default_value(db_tp, &r);
    db.store_nr = r.store_nr;
    db.rec = 1;
    db.pos = 8;
    db
}

/// Create a new record element inside a vector/sorted/index collection.
/// Returns a `DbRef` pointing to the new element with default field values.
/// Bytecode equivalent: `OpNewRecord` in `src/state/io.rs:336`.
pub fn OpNewRecord(
    cell: &std::cell::UnsafeCell<Stores>,
    data: DbRef,
    parent_tp: i32,
    fld: i32,
) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let parent_tp = parent_tp as u16;
    let fld = fld as u16;
    let new_value = stores.record_new(&data, parent_tp, fld);
    stores.set_default_value(
        if fld == u16::MAX {
            stores.content(parent_tp)
        } else {
            stores.content(stores.field_type(parent_tp, fld))
        },
        &new_value,
    );
    new_value
}

/// Finalize a record after its fields have been assigned.
/// For sorted/index collections this inserts the record at the correct position.
/// Bytecode equivalent: `OpFinishRecord` in `src/state/io.rs:772`.
pub fn OpFinishRecord(
    cell: &std::cell::UnsafeCell<Stores>,
    data: DbRef,
    record: DbRef,
    parent_tp: i32,
    fld: i32,
) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores.record_finish(&data, &record, parent_tp as u16, fld as u16);
}

/// Free a database reference.  Closes any associated file handle first.
/// Bytecode equivalent: `OpFreeRef` in `src/state/io.rs:262`.
/// The `name` argument is the loft variable name (e.g. `"var_p"`); it appears in
/// `LOFT_STORE_LOG` output for diagnosing LIFO store-free order violations.
pub fn OpFreeRef(cell: &std::cell::UnsafeCell<Stores>, db: DbRef, name: &str) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    // A generator handle addresses no store — free the coroutine, which releases the heap
    // locals it still owns.  Mirrors the interpreter's `free_ref_db` (loft#835).
    if db.store_nr == NATIVE_COROUTINE_STORE {
        free_native_coroutine(db, stores);
        return;
    }
    if db.store_nr == u16::MAX {
        return;
    }
    if (db.store_nr as usize) >= stores.allocations.len() {
        return;
    }
    // Plan-57 Phase C: single-ownership (ref-count removed) — close the file
    // handle whenever its File store is freed.
    #[cfg(not(host_fs))]
    if !stores.allocations[db.store_nr as usize].free
        && db.rec != 0
        && let Some(&file_type) = stores.names.get("File")
    {
        let stored_type = stores.store(&db).get_u32_raw(db.rec, 4) as u16;
        if stored_type == file_type {
            let file_ref = stores.store(&db).get_i32_raw(db.rec, db.pos + 28);
            if file_ref != i32::MIN && (file_ref as usize) < stores.files.len() {
                stores.files[file_ref as usize] = None;
            }
        }
    }
    stores.free_named(&db, name);
}

/// Plan-57 store-identity gate (`OpStoreTag`) — native runtime parity with the
/// interpreter's `State::store_tag` (`src/state/io.rs`).  Stamps the allocation-site
/// `tag` on the store `db` points to, so a later `OpFreeRefTag` can verify the free
/// corresponds.  Emitted only under the `LOFT_STORE_TAG` gate (a testing build);
/// absent from normal native code.
pub fn OpStoreTag(cell: &std::cell::UnsafeCell<Stores>, db: DbRef, tag: i64) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if db.store_nr != u16::MAX && (db.store_nr as usize) < stores.allocations.len() {
        stores.allocations[db.store_nr as usize].tag = tag as u32;
    }
}

/// Plan-57 store-identity gate (`OpFreeRefTag`) — native runtime parity with the
/// interpreter's `State::free_ref_tag`.  Verifies the store's stamped tag against
/// the free site, then frees (via [`OpFreeRef`]).  Emitted only under the
/// `LOFT_STORE_TAG` gate.
///
/// # Panics
/// Panics on a store-tag mismatch — a wrong-store / cross-owner free — exactly as
/// the interpreter does, so the native and interpreter gates report the same bug.
pub fn OpFreeRefTag(cell: &std::cell::UnsafeCell<Stores>, db: DbRef, tag: i64) {
    {
        let stores: &Stores = unsafe { &*cell.get() };
        if db.store_nr != u16::MAX && (db.store_nr as usize) < stores.allocations.len() {
            let st = &stores.allocations[db.store_nr as usize];
            // `tag == 0` covers a slot reused by a NON-OpDatabase allocator after a
            // tagged store freed it (`free_named` resets the tag to 0).  Mirrors the
            // interpreter's `State::free_ref_tag` exactly.
            assert!(
                st.free || st.tag == 0 || st.tag == tag as u32,
                "store-tag mismatch on free: store #{} has tag {} but OpFreeRefTag expected {}",
                db.store_nr,
                st.tag,
                tag as u32,
            );
        }
    }
    OpFreeRef(cell, db, "");
}

/// Write `s` to standard output, treating a CLOSED stdout as the ordinary end of a pipeline
/// rather than a fault.
///
/// `print!` panics on any write error, so `prog | head` — the most ordinary shell idiom there
/// is — ended in a Rust panic naming a `std` source line; and when stderr shared the closed
/// pipe the panic PRINTER failed too, the process ABORTED, and the crash reporter wrote a
/// report blaming a line of `default/01_code.loft` that has nothing wrong with it
/// (loft#1289).  A reader that stops reading is not this program's error: stop writing and
/// leave, which is what every other tool on a pipeline does.
///
/// Exit **0** rather than by signal.  `head` itself exits 0, and a pipeline written to stop
/// early is doing what it was written to do — under `set -o pipefail` a signal would report
/// the idiom as a failure.
///
/// The interpreter (`fill.rs`) and the `#rust` template the native generator emits both call
/// THIS, so the two backends cannot answer a broken pipe differently.
///
/// # Panics
///
/// On a write error that is NOT a broken pipe — a full disk, an I/O error on a redirect.
/// That is a real fault and keeps the loudness `print!` had; only the closed reader is
/// reinterpreted as an ending.
pub fn host_print(s: &str) {
    use std::io::Write;
    let broken = {
        let mut out = std::io::stdout().lock();
        match out.write_all(s.as_bytes()) {
            Ok(()) => false,
            Err(e) if e.kind() == std::io::ErrorKind::BrokenPipe => true,
            // Anything else — a full disk, an I/O error on a redirect — is a real fault and
            // keeps the loudness `print!` had.
            Err(e) => panic!("failed printing to stdout: {e}"),
        }
    };
    if broken {
        std::process::exit(0);
    }
}

/// Write `s` to standard error, ignoring a write that cannot land.
///
/// The counterpart of [`host_print`], and it does NOT exit: stderr being closed says nothing
/// about the program's own output, so `prog 2>/dev/full` or a reader that stopped reading the
/// diagnostics stream must not end the run.  What it must never do is panic — a panic whose
/// message cannot be printed is what turns a broken pipe into a SIGABRT and a crash report
/// (loft#1289).
pub fn host_eprint(s: &str) {
    use std::io::Write;
    let _ = std::io::stderr().write_all(s.as_bytes());
}

/// conditionally free `placeholder` — only when its `store_nr`
/// differs from `witness`'s.  Emitted for `__ref_N` work-refs whose
/// value might alias a still-live Reference variable in the current
/// scope (adoption vs. fresh-store is a runtime choice the caller's
/// compiler cannot resolve statically).  Bytecode equivalent:
/// `OpFreeRefIfDistinct` in `src/fill.rs`.
pub fn OpFreeRefIfDistinct(
    cell: &std::cell::UnsafeCell<Stores>,
    placeholder: DbRef,
    witness: DbRef,
) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores.free_displaced(&placeholder, &witness);
}

/// Free an `on=4` iteration scratch at loop exit — a dedicated store goes back
/// whole, a co-located one goes back as the two records it claimed inside the
/// source store.  Both cases live in `Stores::free_iteration_scratch`, so the
/// two backends cannot drift.  Bytecode equivalent: `free_scratch` in `src/fill.rs`.
pub fn OpFreeScratch(cell: &std::cell::UnsafeCell<Stores>, scratch: DbRef) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores.free_iteration_scratch(&scratch);
}

/// Format a database record as text and append it to the output string.
/// Bytecode equivalent: `OpFormatDatabase` in `src/state/io.rs:278`.
pub fn OpFormatDatabase(
    cell: &std::cell::UnsafeCell<Stores>,
    output: &mut String,
    record: DbRef,
    db_tp: i32,
    db_format: i32,
) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let mut s = String::new();
    ShowDb {
        stores,
        store: record.store_nr,
        rec: record.rec,
        pos: record.pos,
        known_type: db_tp as u16,
        pretty: db_format & 1 > 0,
        json: db_format & 2 > 0,
        loft: false,
        dump: false,
        compact: false,
        max_depth: u16::MAX,
        max_elements: u16::MAX,
    }
    .write(&mut s, 0);
    output.push_str(&s);
}

/// @PLN133 S8 — the generated `n_lazy_fetch`, as a pointer this runtime can call.
///
/// The shape is exactly what the generator emits for the one signature
/// [`crate::data::Data::lazy_fetch_driver`] admits, and that is the point of the
/// check living there: the interpreter pushes arguments in this order and the
/// generator installs a pointer of this type, so a signature the two disagreed
/// about could not exist.
pub type LazyFetchFn = fn(&std::cell::UnsafeCell<Stores>, DbRef, &str, i64, &str) -> i64;

/// The installed drivers, keyed by the ELEMENT TYPE each serves.
///
/// @PLN133 S9 — a table rather than the one word this was, because one driver per
/// program was not merely a limit: nothing checked that the driver a miss reached
/// was declared for THAT collection, so a second lazily-bound element type ran
/// the first type's driver and filled its collection with the wrong records.
///
/// The key is a NAME because the two backends count types in different spaces —
/// a parse-time `Definition` and a runtime `Stores::types` entry — and a name is
/// the one key both hold without a mapping to keep in step.
///
/// Written once by generated `init()` before anything runs and only read
/// afterwards, so the lock is uncontended in practice; a `par` worker taking a
/// fault reads the same table rather than its own copy.
static LAZY_FETCH: std::sync::Mutex<Vec<(String, usize)>> = std::sync::Mutex::new(Vec::new());

/// Why this program's drivers were refused, if they were.
///
/// The interpreter asks `Data` at every miss, so a malformed driver — or two for
/// one element type — reports its reason to whichever lookup happens first.
/// `--native` cannot ask `Data` at all, so without this it registered nothing and
/// reported *"needs a loft driver"*: the same program, two different reasons,
/// and the one that named the actual mistake was the one you did not get if you
/// compiled. Generated `init()` installs the refusal so both backends answer the
/// sentence `Data` wrote.
static LAZY_FETCH_REFUSAL: std::sync::Mutex<Option<String>> = std::sync::Mutex::new(None);

thread_local! {
    /// @PLN133 S8 — is this thread inside a lazy DRIVER right now?
    ///
    /// It changes what a fault MEANS. An ordinary loft call that overflows the
    /// stack is a program bug and halting is right; the same overflow inside a
    /// FETCH is not, because @PLN129's contract is C80 — a failed fetch reports
    /// through `store_lazy_error` and the lookup answers null. So a buggy driver
    /// must not turn a lookup into a program halt, which is what moving the
    /// source from Rust to loft would otherwise have cost.
    ///
    /// Thread-local rather than global: a `par` worker running its own fetch is
    /// its own answer.
    static IN_LAZY_DRIVER: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

/// Is a fault on this thread a driver's, and therefore containable?
///
/// Read by `cr_stack_overflow`, which exits the process for an ordinary overflow
/// and unwinds for this one, and by the panic hook, which stays silent for a
/// fault that is about to be reported through arc C's channel instead.
#[must_use]
pub fn in_lazy_driver() -> bool {
    IN_LAZY_DRIVER.with(std::cell::Cell::get)
}

/// Install one lazy driver, under the element type it serves. Emitted by
/// generated `init()`, once per driver.
///
/// This is the whole of what `--native` was missing: `OpGetRecord` is compiled
/// into libloft and cannot see a function the generator wrote, so the generator
/// hands each one over instead.
///
/// `element` is the same key the interpreter looks up (`Data::lazy_fetch_drivers`
/// reads it off the driver's collection parameter), which is what stops the two
/// backends disagreeing about which driver a miss reaches.
pub fn register_lazy_fetch(element: &str, f: LazyFetchFn) {
    let mut table = LAZY_FETCH
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    // Replace rather than append on a repeat: `init()` runs once, but a host
    // embedding that re-inits must not accumulate two answers for one type.
    if let Some(slot) = table.iter_mut().find(|(e, _)| e == element) {
        slot.1 = f as usize;
    } else {
        table.push((element.to_string(), f as usize));
    }
    // A contained driver fault unwinds, and an unwind prints unless a hook says
    // otherwise. Installed HERE — at init, before any thread exists — rather than
    // around each call, because swapping the process-wide hook per fetch would
    // race with any other thread that panics.
    crate::crash_report::install_panic_hook();
}

/// Install the reason this program's drivers were refused. Emitted by generated
/// `init()` in place of any registration, so a miss reports the mistake rather
/// than its symptom.
pub fn register_lazy_fetch_refusal(why: &str) {
    *LAZY_FETCH_REFUSAL
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(why.to_string());
}

/// The refusal, if the drivers were refused.
fn lazy_fetch_refusal() -> Option<String> {
    LAZY_FETCH_REFUSAL
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .clone()
}

/// The driver installed for this element type, if the program declared one.
fn lazy_fetch_fn(element: &str) -> Option<LazyFetchFn> {
    let table = LAZY_FETCH
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let p = table.iter().find(|(e, _)| e == element).map(|(_, p)| *p)?;
    // Safe by construction: the only writer is `register_lazy_fetch`, whose
    // parameter is already typed `LazyFetchFn`.
    Some(unsafe { std::mem::transmute::<usize, LazyFetchFn>(p) })
}

/// Look up a record in a collection by key values.
/// Bytecode equivalent: `OpGetRecord` in `src/state/io.rs` (`State::get_record`).
///
/// The one exit answers the record as a VALUE: `nullref` for a miss, whichever arm of the
/// lookup missed (`DbRef::or_null`, @FR-L-Null) — the interpreter's twin normalises at its
/// exit the same way, so the two backends hand back one spelling of absence.
pub fn OpGetRecord(
    cell: &std::cell::UnsafeCell<Stores>,
    data: DbRef,
    db_tp: i32,
    key: &[crate::keys::Content],
) -> DbRef {
    get_record_lookup(cell, data, db_tp, key).or_null()
}

/// [`OpGetRecord`]'s lookup: resident first, then the lazy source.  Every miss arm answers
/// a reference with no record and the caller spells it as a value.
fn get_record_lookup(
    cell: &std::cell::UnsafeCell<Stores>,
    data: DbRef,
    db_tp: i32,
    key: &[crate::keys::Content],
) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if data.rec == 0 {
        DbRef::NULL
    } else {
        // @PLN129 arc A — same miss path as the interpreter, so both backends
        // agree about what is resident. @PLN133 S8 splits the miss from the
        // fetch at both callers rather than inside `Stores`; here it costs
        // nothing (generated code is Rust calling Rust), and it keeps the two
        // backends reading the same two calls in the same order.
        let found = stores.find(&data, db_tp as u16, key);
        if found.rec != 0 {
            return found;
        }
        // @PLN133 S8 — a source served by a LOFT driver. Same shape as the
        // interpreter's: run the driver, then re-run the lookup, because the
        // collection stays the only authority on what is resident.
        //
        // The driver arrives as a POINTER generated `init()` installed, because
        // this helper is compiled into libloft and cannot see a function the
        // generator wrote. Two mechanisms, one answer.
        // @PLN133 S9 — the driver is chosen by the collection's ELEMENT TYPE, the
        // same key the interpreter looks up by, so a program with several
        // lazily-bound types reaches the right one on both backends. The one
        // installed pointer this replaced was called for every collection
        // whatever it was declared for.
        //
        // It is also what decides whether a source core CAN drive goes to loft
        // instead: a declared driver wins. A refused driver SET answers `true`
        // here for the same reason it does on the interpreter — the refusal must
        // be reported, not swallowed by a silent fall back to Rust.
        let element = stores.element_type_name(db_tp as u16).to_string();
        let have_driver = lazy_fetch_refusal().is_some() || lazy_fetch_fn(&element).is_some();
        if let Some(source) = stores.lazy_loft_source(&data, have_driver) {
            // A refused driver set poisons every lookup, exactly as it does on the
            // interpreter — which re-asks `Data` at each miss and gets the same
            // `Err` back. Reporting the symptom here instead would mean the
            // backend you compiled with hid which mistake you made.
            if let Some(why) = lazy_fetch_refusal() {
                stores.lazy_fail(&data, &why);
                return DbRef {
                    store_nr: data.store_nr,
                    rec: 0,
                    pos: 0,
                };
            }
            let Some(driver) = lazy_fetch_fn(&element) else {
                // Failure path 1: a backend that is not here reads as
                // UNREACHABLE and names itself, never as "no such row". The
                // message has one home so the two backends cannot word it
                // differently.
                stores.lazy_fail(
                    &data,
                    &crate::database::lazy::no_lazy_driver(&source, &element),
                );
                return DbRef {
                    store_nr: data.store_nr,
                    rec: 0,
                    pos: 0,
                };
            };
            // One key, whichever spelling it arrived in — the same limit the
            // interpreter has, and for the same reason: fetching the WRONG row
            // is worse than answering absent.
            let (key_int, key_text) = match key {
                [crate::keys::Content::Long(k)] => (*k, String::new()),
                [crate::keys::Content::Str(s)] => (0, s.str().to_string()),
                _ => {
                    stores.lazy_fail(
                        &data,
                        "a composite key cannot be fetched — a driver is given one key",
                    );
                    return DbRef {
                        store_nr: data.store_nr,
                        rec: 0,
                        pos: 0,
                    };
                }
            };
            // The driver's fault is CONTAINED, exactly as the interpreter
            // contains it. There is no dispatch loop to unwind here, so the
            // depth guard raises instead of exiting and this catches it — the
            // one place in generated-code execution where a fault is not the
            // program's to die of.
            //
            // The window is the same teardown the interpreter runs: Rust's
            // unwind runs its own drop glue, but a loft store is freed by an
            // explicit call the unwind skips exactly as the interpreter's fault
            // skips its scope-exit op — measured identical on both backends.
            IN_LAZY_DRIVER.with(|f| f.set(true));
            let outer_watch = stores.lazy_watch_begin();
            let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                driver(cell, data, &source, key_int, &key_text)
            }));
            IN_LAZY_DRIVER.with(|f| f.set(false));
            // `stores` was borrowed from `cell` and the driver borrowed it too,
            // so it is re-taken here rather than reused.
            let stores: &mut Stores = unsafe { &mut *cell.get() };
            stores.lazy_watch_end(outer_watch, outcome.is_err());
            match outcome {
                Ok(1 | 0) => {}
                // A driver that answered something else did not follow the
                // contract, and guessing which of the two it meant is how an
                // unreachable source starts reading as an empty table.
                Ok(answer) => stores.lazy_fail(
                    &data,
                    &format!(
                        "`lazy_fetch` answered {answer}; it must answer 1 (inserted) or 0 (absent)"
                    ),
                ),
                Err(payload) => {
                    let why = payload
                        .downcast_ref::<&str>()
                        .map(|s| (*s).to_string())
                        .or_else(|| payload.downcast_ref::<String>().cloned())
                        .unwrap_or_else(|| "the driver faulted".to_string());
                    stores.lazy_fail(&data, &why);
                }
            }
            return stores.find(&data, db_tp as u16, key);
        }
        stores.fetch_missing(&data, db_tp as u16, key)
    }
}

/// Extract a substring from a text value.
///
/// `from` and `till` are **byte** indices into the UTF-8 string (matching the
/// bytecode interpreter in `src/state/text.rs`):
/// - `from` is snapped *backward* to the start of its containing character if
///   it points into the middle of a multi-byte sequence.
/// - `till` is snapped *forward* past continuation bytes so it lands on the
///   next character boundary.
/// - A negative bound counts from the end of the string (`bound += len`), floored at the
///   start of the string — the rule `@FR-Slice-Value` gives every value slice.
///
/// Bytecode equivalent: `State::get_text_sub` in `src/state/text.rs`.
#[must_use]
pub fn OpGetTextSub(text: &str, from: i64, till: i64) -> &str {
    let bytes = text.as_bytes();
    let len = bytes.len() as i64;
    let from = if from < 0 { (from + len).max(0) } else { from };
    if from >= len {
        return "";
    }
    // Snap `from` backward to the start of the current character.
    let mut f = from as usize;
    while f > 0 && bytes[f] & 0xC0 == 0x80 {
        f -= 1;
    }
    // Resolve negative `till` to a forward byte offset.
    let t_raw = if till < 0 { len + till } else { till };
    if t_raw <= f as i64 {
        return "";
    }
    // Clamp to string length.
    let mut t = t_raw.min(len) as usize;
    // Snap `till` forward past any continuation bytes so it lands on a
    // character boundary (mirrors the interpreter behaviour).
    while t < bytes.len() && bytes[t] & 0xC0 == 0x80 {
        t += 1;
    }
    &text[f..t]
}

/// Return the byte size of a database record's type.
/// Bytecode equivalent: `OpSizeofRef` in `src/state/io.rs:290`.
#[must_use]
pub fn OpSizeofRef(cell: &std::cell::UnsafeCell<Stores>, db: DbRef) -> i64 {
    let stores: &Stores = unsafe { &*cell.get() };
    if db.rec == 0 {
        0
    } else {
        let tp = stores.store(&db).get_u32_raw(db.rec, 4) as u16;
        i64::from(stores.size(tp))
    }
}

/// Parse a text representation into a database record.
/// Bytecode equivalent: `State::db_from_text` in `src/state/io.rs:780`.
#[must_use]
pub fn db_from_text(stores: &mut Stores, val: &str, db_tp: u16) -> DbRef {
    // @P372: size the target record to the struct, not a fixed 8 words — see
    // the mirror in `State::db_from_text` (`src/state/io.rs`) for the full
    // rationale.  A fixed `database(8)` (64 bytes) left only 56 bytes for the
    // struct (written at `pos: 8`), so a struct > 56 bytes overflowed its tail
    // field into the adjacent block header, and a later `claim` spun forever in
    // `claim_scan`.  Keep a floor of 8 words.
    let words = std::cmp::max(8, 1 + u32::from(stores.size(db_tp)).div_ceil(8));
    let db = stores.database(words);
    let into = DbRef {
        store_nr: db.store_nr,
        rec: db.rec,
        pos: 8,
    };
    stores.set_final_default_value(db_tp, &into);
    stores.last_parse_errors.clear();
    if let Some(err) = stores.parse(val, db_tp, &into) {
        stores.last_parse_errors.push(err);
    }
    into
}

/// Return the parse errors from the last `Type.parse()` call as a single
/// newline-separated string.  Called by the `#errors` accessor.
// @PLN10 — owned `String` (no scratch).  In lockstep with
// `generation::native_returns_owned_string`, which makes the generated `n_*`
// wrapper `-> String` so wrapper and body agree on every backend (incl. wasip2).
pub fn i_parse_errors(stores: &mut Stores) -> String {
    let msg = stores.last_parse_errors.join("\n");
    stores.last_parse_errors.clear();
    msg
}

/// Push a constraint-check error to the parse error list.
pub fn i_parse_error_push(stores: &mut Stores, msg: &str) {
    stores.last_parse_errors.push(msg.to_owned());
}

/// Return the JSON parse / schema-walk errors from the last `json_parse()`
/// or `Struct.parse(JsonValue)` call as a single `|`-separated string.
/// Mirrors the interpreter's `n_json_errors` (`src/native.rs`) which does
/// NOT clear the buffer — errors persist across `json_errors()` reads
/// until the next successful parse implicitly clears them.
// @PLN10 — owned `String` (no scratch); same gate as `i_parse_errors`.
pub fn i_json_errors(stores: &mut Stores) -> String {
    stores.last_json_errors.join("|")
}

/// Deep-copy a database record: copies the raw bytes and duplicates
/// all owned sub-structures (text fields, vectors, etc.).
/// Bytecode equivalent: `State::copy_record` in `src/state/io.rs:697`.
pub fn OpCopyRecord(cell: &std::cell::UnsafeCell<Stores>, data: DbRef, to: DbRef, tp: i32) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    // @PLAN51 Cluster II — true alias copy is a no-op.  Same rationale
    // as `src/state/io.rs::copy_record`: when data and to refer to the
    // SAME slot, remove_claims would free nested vector / text records
    // that copy_block / copy_claims then need to read, corrupting the
    // shared data.  Short-circuit before any destructive op.
    if data == to {
        let _ = tp;
        return;
    }
    // @PLN25 — mirror `state/io.rs::do_copy_record`: a NULL source
    // (`store_nr == u16::MAX`) has no store to read; `store(&data)` would index
    // `allocations[65535]` and panic (`allocation.rs:560`).  Guards the
    // pre-existing crash on `vec[i] = <runtime-null>` into a non-nullable inline
    // element — leave the destination unchanged rather than crash.
    if data.store_nr == u16::MAX {
        return;
    }
    // @FR-L-Null, the DESTINATION half — the twin of `state/io.rs::do_copy_record`'s.  An
    // out-of-range element write hands this a null PLACE (loft#1374 made an absent read
    // answer `nullref`); there is nothing to write into, so the write is dropped.
    if to.store_nr == u16::MAX {
        return;
    }
    // mirror `state/io.rs::copy_record`'s tag handling and
    // cleanup.  The bytecode form masks the high bit of `tp` before
    // indexing into `stores.types` (0x8000 marks "free source after
    // copy").  The mask must be applied before indexing and the
    // flagged source freed after the copy; any caller that sets the
    // flag — e.g. `copy_ref` on a struct-returning call's result —
    // otherwise panics at `Types::size()` with an out-of-bounds
    // index.  Also missing:
    // `remove_claims` before the overwrite, which the bytecode form
    // uses to free the destination's nested vectors/strings so a
    // reassignment doesn't double-free on scope exit.
    let raw_tp = tp as u16;
    let free_source = raw_tp & 0x8000 != 0;
    let tp = raw_tp & 0x7FFF;
    let size = u32::from(stores.size(tp));
    if std::env::var("LOFT_TRACE_COPY").is_ok() {
        crate::loft_eprintln!(
            "[copy] OpCopyRecord src=#{}@{},{} dst=#{}@{},{} tp={tp} size={size} free_src={free_source}",
            data.store_nr,
            data.rec,
            data.pos,
            to.store_nr,
            to.rec,
            to.pos,
        );
    }
    stores.remove_claims(&to, tp);
    stores.copy_block(&data, &to, size);
    stores.copy_claims(&data, &to, tp);
    // @P317 — LOFT_LOG=copy_check (native): warn on nested-length divergence.
    if stores.copy_check_enabled() {
        stores.report_copy_mismatches(&data, &to, tp, "OpCopyRecord");
    }
    if free_source
        && data.store_nr != to.store_nr
        && !stores.is_stack_store(data.store_nr)
        && !stores.allocations[data.store_nr as usize].free
        && !stores.allocations[data.store_nr as usize].read_only
        && !stores.allocations[data.store_nr as usize].is_free_protected()
    {
        stores.free(&data);
    }
}

/// @P295 — deep-copy a keyed collection (`sorted`/`hash`/`index`) into a
/// keyed-collection LOCAL `dest`, replacing its prior contents.  Native
/// twin of `State::replace_keyed`.  No `copy_block`: a keyed local is a
/// `DbRef` to a dedicated store whose collection header is at `(store, 1,
/// 8)`, so `remove_claims(dest)` + `copy_claims(src, dest, tp)` (per-kind
/// index rebuild) is the complete copy.  `tp`'s `0x8000` high bit frees the
/// source store after the copy (fresh-storage RHS like `s = build()`).
pub fn OpReplaceKeyed(cell: &std::cell::UnsafeCell<Stores>, src: DbRef, dest: DbRef, tp: i32) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let raw_tp = tp as u16;
    let free_source = raw_tp & 0x8000 != 0;
    let tp = raw_tp & 0x7FFF;
    // loft#1150 — an ABSENT source copies NOTHING; the twin of the guard in
    // `State::replace_keyed`, which carries the reasoning.
    if src.store_nr == u16::MAX {
        stores.remove_claims(&dest, tp);
        stores.mark_collection_absent(&dest);
        return;
    }
    stores.remove_claims(&dest, tp);
    stores.copy_claims(&src, &dest, tp);
    // @P317 — LOFT_LOG=copy_check (native): warn on nested-length divergence.
    if stores.copy_check_enabled() {
        stores.report_copy_mismatches(&src, &dest, tp, "OpReplaceKeyed");
    }
    if free_source
        && src.store_nr != dest.store_nr
        // Sentinel guard: the `allocations[..]` prechecks below index by store_nr.
        && src.store_nr != u16::MAX
        && !stores.is_stack_store(src.store_nr)
        && !stores.allocations[src.store_nr as usize].free
        && !stores.allocations[src.store_nr as usize].read_only
        && !stores.allocations[src.store_nr as usize].is_free_protected()
    {
        stores.free(&src);
    }
}

/// @P307 — clear a keyed collection (`sorted`/`hash`/`index`) held in a
/// STRUCT FIELD: free its element records + bucket/tree array and zero the
/// field's claim pointer, so a later `+= [..]` re-initialises it.  Native
/// twin of the `OpClearKeyed` interp op (`#rust` body
/// `s.database.remove_claims`).  Unlike the keyed-LOCAL clear (OpDatabase,
/// which resets a dedicated store), a field's collection lives as a claim
/// inside its struct's store, so `remove_claims` is the in-place free.
///
/// loft#898 — `tp`'s `0x8000` bit marks a SECONDARY VIEW of a linked group;
/// `remove_claims_keyed` is the shared decode, so this stays the twin of the
/// interpreter's `#rust` template rather than a second reading of the bit.
pub fn OpClearKeyed(cell: &std::cell::UnsafeCell<Stores>, dest: DbRef, tp: i32) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores.remove_claims_keyed(&dest, tp as u16);
}

/// @P305 — `coll[key] = value` insert-or-replace into a keyed collection.
/// Native twin of the `OpSetKeyed` interp op / `State::set_keyed`.  `tp`'s
/// `0x8000` bit frees `value`'s store after the deep copy (caller temp).
pub fn OpSetKeyed(cell: &std::cell::UnsafeCell<Stores>, collection: DbRef, value: DbRef, tp: i32) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let raw = tp as u16;
    let free_source = raw & 0x8000 != 0;
    stores.set_keyed(&collection, &value, raw & 0x7FFF, free_source);
}

/// Sort a vector in-place using the element type's natural ordering.
/// Dispatches on element type:
///   - text → `sort_text_vector` (lexicographic; sorts offsets by
///     the strings they point at)
///   - integer / float / single → `sort_vector` (primitive in-place)
///
/// Bytecode equivalent: `sort_vector` in `src/fill.rs:1835`.
pub fn OpSortVector(cell: &std::cell::UnsafeCell<Stores>, data: DbRef, db_tp: i32) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let db_tp = db_tp as u16;
    if stores.is_text_type(db_tp) {
        vector::sort_text_vector(&data, &mut stores.allocations);
        return;
    }
    let elem_size = stores.size(db_tp);
    let is_float = db_tp == 2 || db_tp == 3;
    vector::sort_vector(&data, elem_size, is_float, &mut stores.allocations);
}

/// Insert a new default-valued element at `index` in a vector, shifting later elements right.
/// Returns a `DbRef` pointing to the newly inserted element.
/// Bytecode equivalent: `State::insert_vector` in `src/state/io.rs:819`.
pub fn OpInsertVector(
    cell: &std::cell::UnsafeCell<Stores>,
    data: DbRef,
    size: i32,
    index: i64,
    db_tp: i32,
) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let new_value = vector::insert_vector(&data, size as u32, index, &mut stores.allocations);
    stores.set_default_value(db_tp as u16, &new_value);
    new_value
}

/// P213: read element [0] of a vector field as a `DbRef`, or null
/// when the vector is empty.  Used by capturing-closure-in-struct-
/// field reads to extract the closure record's `DbRef` from the
/// host's `cb__closure_rec` vector field.  Mirrors
/// `vector_first_or_null` in `src/fill.rs`.
#[must_use]
pub fn op_vector_first_or_null(stores: &[crate::store::Store], host: &DbRef) -> DbRef {
    let store = crate::keys::store(host, stores);
    let vec_rec = store.get_u32_raw(host.rec, host.pos);
    if vec_rec == 0 {
        return DbRef::NULL;
    }
    let length = store.get_u32_raw(vec_rec, 4);
    if length == 0 {
        DbRef::NULL
    } else {
        DbRef {
            store_nr: host.store_nr,
            rec: vec_rec,
            pos: 8,
        }
    }
}

/// Return the UTF-8 byte length of a character (encoded as `i32` in loft).
/// Returns 0 for the null character sentinel.
/// Bytecode equivalent: `State::length_character` in `src/state/text.rs:54`.
#[must_use]
pub fn OpLengthCharacter(_cell: &std::cell::UnsafeCell<Stores>, c: i32) -> i64 {
    let ch = ops::to_char(c);
    if ch == '\0' {
        0
    } else {
        i64::try_from(ch.len_utf8()).unwrap_or(0)
    }
}

/// Number of elements in a `spatial<T[x,y]>` (radix / Morton tree) collection.
/// Thin wrapper over the crate-private `radix_db::count` so the `#rust` `len`
/// template reaches it through the pub `codegen_runtime` module on both backends
/// (mirrors how `hash::count` backs `len(both: hash)`).
#[must_use]
pub fn spatial_len(coll: &DbRef, stores: &[crate::store::Store]) -> u32 {
    crate::radix_db::count(coll, stores)
}

/// Number of records in a trie.  The cached tree length, as for a spatial index.
#[must_use]
pub fn trie_len(coll: &DbRef, stores: &[crate::store::Store]) -> u32 {
    crate::trie_db::count(coll, stores)
}

/// Pack a (current-position, finish) pair into a single i64 iterator state.
/// High 32 bits = finish; low 32 bits = cur.
/// `finish == u32::MAX` signals that iteration is complete.
fn pack_iter(cur: u32, finish: u32) -> i64 {
    ((u64::from(finish) << 32) | u64::from(cur)).cast_signed()
}

/// Build a minimal `DbRef` pointing at record `rec` with field offset `pos`.
fn iter_ref(data: &DbRef, rec: u32, pos: u16) -> DbRef {
    DbRef {
        store_nr: data.store_nr,
        rec,
        pos: u32::from(pos),
    }
}

/// Initialize a sorted/index iterator state and return it as a packed `i64`.
///
/// `on` encodes collection type and flags:
/// - bits 0–5: collection type (1 = red-black tree / index, 2 = sorted vector)
/// - bit 6: reverse iteration
/// - bit 7: inclusive end (if clear, end is exclusive)
///
/// `arg` is the element size in bytes (sorted) or the tree-fields offset (index).
/// `keys` describes the key fields in the collection type.
/// `from` / `till` are the from/till key values; empty slices mean start/end of collection.
///
/// The returned `i64` is consumed by [`OpStep`].
/// Bytecode equivalent: `State::iterate` in `src/state/io.rs`.
#[must_use]
pub fn OpIterate(
    cell: &std::cell::UnsafeCell<Stores>,
    data: DbRef,
    on: i32,
    arg: i32,
    keys: &[Key],
    from: &[Content],
    till: &[Content],
) -> i64 {
    let stores: &Stores = unsafe { &*cell.get() };
    if data.rec == 0 {
        return pack_iter(u32::MAX, u32::MAX);
    }
    let reverse = (on & 64) != 0;
    let ex = (on & 128) == 0;
    let all = &stores.allocations;
    match on & 63 {
        2 => {
            // sorted vector: arg = element size in bytes
            //
            // An EMPTY from/till means "no constraint on this side" and must be read as
            // the collection's own edge — `sorted_find` with no key returns 0, which is a
            // real position, so using it unguarded made an open END finish at 0 and the
            // loop visit nothing.  `for r in s[1..]` and `s[..]` silently summed to zero
            // on `--native` while the interpreter (`State::iterate`, which has always had
            // these cases) returned the right answer: a wrong ANSWER, not a crash, and
            // only on one backend (loft#689).  Mirror `State::iterate` exactly.
            let size = arg as u16;
            let sorted_rec_raw = all[data.store_nr as usize].get_i32_raw(data.rec, data.pos);
            let sorted_rec = if sorted_rec_raw <= 0 {
                0
            } else {
                sorted_rec_raw as u32
            };
            let vec_len = if sorted_rec == 0 {
                0
            } else {
                all[data.store_nr as usize].get_u32_raw(sorted_rec, 4)
            };
            if reverse {
                // loft#691 (and see `State::iterate`, the shared contract) — `start` is
                // one PAST the first element to visit (`>= vec_len` is the not-started
                // sentinel) and `finish` is the LOWEST position to visit.  The lower
                // bound is always INCLUSIVE — `ex` describes the upper one — so it is
                // searched with `true`, exactly as the forward branch does.
                let s = if till.is_empty() {
                    vec_len
                } else {
                    vector::sorted_find(&data, ex, size, all, keys, till).0
                };
                let f = if from.is_empty() {
                    0
                } else {
                    vector::sorted_find(&data, true, size, all, keys, from).0
                };
                pack_iter(s, f)
            } else {
                let s = if from.is_empty() {
                    0
                } else {
                    vector::sorted_find(&data, true, size, all, keys, from).0
                };
                let start = if s == 0 { u32::MAX } else { s - 1 };
                let finish = if till.is_empty() {
                    vec_len
                } else {
                    let (t, cmp) = vector::sorted_find(&data, ex, size, all, keys, till);
                    if ex || cmp { t } else { t + 1 }
                };
                pack_iter(start, finish)
            }
        }
        1 => {
            // red-black tree / index: arg = fields offset.  The cursor derivation is
            // shared with `State::iterate` (loft#691) — the two had their own copies
            // and drifted apart.
            let (start, finish) =
                tree::range_cursors(&data, arg as u16, all, keys, from, till, ex, reverse);
            pack_iter(start, finish)
        }
        3 | 4 => {
            // C60 piece 3: Ordered iteration — `data` points at a header record whose
            // offset-4 word is the u32-stride rec-nr vector rec-nr.  on=4
            // (fresh-scratch hash/radix) shares this cursor setup.
            //
            // The derivation is shared with `State::iterate` (loft#904) — the two had
            // their own copies of the bounded arms, expressed in SLOT INDICES where the
            // stepper walks BYTE OFFSETS, and had already drifted apart without anything
            // noticing, because a bounded or reverse `ordered` walk never consumed them.
            let (start, finish) =
                vector::ordered_range_cursors(&data, all, keys, from, till, ex, reverse);
            pack_iter(start, finish)
        }
        _ => pack_iter(u32::MAX, u32::MAX),
    }
}

/// Advance the iterator to the next element and return a `DbRef` pointing to it.
/// Returns a `DbRef` with `rec == 0` when iteration is complete.
///
/// `iter` is the mutable `i64` state returned by [`OpIterate`]; it is updated in place.
/// `on` and `arg` must match the corresponding `OpIterate` call.
///
/// Bytecode equivalent: `State::step` in `src/state/io.rs`.
pub fn OpStep(
    cell: &std::cell::UnsafeCell<Stores>,
    iter: &mut i64,
    data: DbRef,
    on: i32,
    arg: i32,
) -> DbRef {
    let stores: &Stores = unsafe { &*cell.get() };
    let mut cur = (*iter as u64) as u32;
    let mut finish = ((*iter as u64) >> 32) as u32;

    if data.rec == 0 || finish == u32::MAX {
        return stores.element_reference(&data, i32::MAX);
    }

    let reverse = (on & 64) != 0;
    let all = &stores.allocations;

    let result = match on & 63 {
        2 => {
            // sorted vector: arg = element size
            let mut pos = if cur == u32::MAX {
                i32::MAX
            } else {
                cur as i32
            };
            if reverse {
                vector::vector_step_rev(&data, &mut pos, all);
                // loft#691 — mirror of the forward `pos >= finish` below: stop once the
                // cursor drops below the lowest in-range position.  `finish == 0` (no
                // lower bound) never trips.
                if pos != i32::MAX && (pos as u32) < finish {
                    pos = i32::MAX;
                }
                if pos == i32::MAX {
                    finish = u32::MAX;
                }
            } else {
                vector::vector_step(&data, &mut pos, all);
                if pos as u32 >= finish {
                    pos = i32::MAX;
                }
            }
            cur = pos as u32;
            let byte_pos = if pos == i32::MAX {
                i32::MAX
            } else {
                8 + pos * arg
            };
            if pos == i32::MAX {
                finish = u32::MAX;
            }
            stores.element_reference(&data, byte_pos)
        }
        1 => {
            // red-black tree / index: arg = fields offset
            let fields = arg as u16;
            let store = crate::keys::store(&data, all);
            let next_rec = if cur == 0 {
                if reverse {
                    tree::last(&data, fields, all).rec
                } else {
                    tree::first(&data, fields, all).rec
                }
            } else if reverse {
                tree::previous(store, &iter_ref(&data, cur, fields))
            } else {
                tree::next(store, &iter_ref(&data, cur, fields))
            };
            if next_rec == finish {
                finish = u32::MAX;
            }
            cur = next_rec;
            DbRef {
                store_nr: data.store_nr,
                rec: next_rec,
                pos: 8,
            }
        }
        3 | 4 => {
            // C60 piece 3: Ordered iteration over the u32-stride rec-nr scratch.
            // Shares `vector::step_ordered` with the interpreter (src/state/io.rs).
            // on=4 (fresh-scratch hash/radix) yields in the source store from the header.
            let (elem, new_pos) = vector::step_ordered(&data, cur, all, on & 63 == 4, reverse);
            cur = new_pos;
            // `finish` bounds the range in the cursor's own BYTE-OFFSET unit, and 0 means
            // no bound — see the twin in `State::step` (`src/state/io.rs`), and keep the
            // two in step.
            let past = finish != 0
                && new_pos != i32::MAX as u32
                && if reverse {
                    new_pos < finish
                } else {
                    new_pos >= finish
                };
            if past {
                finish = u32::MAX;
                stores.element_reference(&data, i32::MAX)
            } else {
                elem
            }
        }
        _ => stores.element_reference(&data, i32::MAX),
    };

    // on=4's dedicated scratch store (read-only source) is freed by the loop epilogue's
    // OpFreeScratch, not here — that also covers an early break.
    *iter = pack_iter(cur, finish);
    result
}

/// Read `path` as UTF-8 text into `buf` — the single home for the read behind
/// `file(p).content()`, called by the interpreter (`State::get_file_text`) and
/// by native codegen (`OpGetFileText`) alike, so the two cannot drift.
///
/// Leaves `buf` EMPTY when the file cannot be opened or its bytes are not valid
/// UTF-8, and warns on the latter.  Emptiness alone does not tell the caller
/// which happened; the loft-level `content()` reads the file's byte size beside
/// it and answers null when a file that HAS bytes yielded no text (loft#829).
#[cfg(not(host_fs))]
pub fn read_file_text_into(path: &str, buf: &mut String) {
    buf.clear();
    let Ok(mut f) = File::open(path) else { return };
    match f.read_to_string(buf) {
        Ok(_) => {}
        Err(e) if e.kind() == std::io::ErrorKind::InvalidData => {
            buf.clear();
            let size = std::fs::metadata(path).map_or(0, |m| m.len());
            crate::loft_eprintln!(
                "warning: file({path:?}).content() got non-UTF-8 bytes ({size} bytes in \
                 file) — returning null. Read the bytes exactly with `read_bytes(path)`, \
                 or a field at a time with `f#format = LittleEndian; f#read(n)` (or \
                 `BigEndian`); see the loft-write skill § File I/O."
            );
        }
        Err(_) => buf.clear(),
    }
}

// ─── loft#851  The page's filesystem ──────────────────────────────────────────
//
// Under `host_fs` the file lives on the JS host, not behind a `std::fs::File`
// handle, so there is no `stores.files[]` entry and no OS cursor.  The host owns
// BOTH: it resolves the path against its own working directory, and it keeps a
// per-path read/write cursor (`host_fs_seek` / `host_fs_get_cursor`).  That is
// why the browser bodies below pass the RAW path — `resolve_path` re-homes
// against a program anchor that exists only where there is a real filesystem to
// anchor to.
//
// Each of these mirrors the interpreter's browser branch in `src/state/io.rs`
// line for line.  They are the same contract reached from two backends, and
// #851's report is exactly what happens when only one of them has it.

/// The path recorded in a loft `File` record.
#[cfg(host_fs)]
fn file_record_path(stores: &Stores, file: &DbRef) -> String {
    let store = stores.store(file);
    store
        .get_str(store.get_u32_raw(file.rec, file.pos + 24))
        .to_owned()
}

/// Read `path` as UTF-8 text into `buf` through the host bridge.  Leaves `buf`
/// EMPTY when the path is absent or its bytes are not text — the same two
/// outcomes the native reader collapses, so `content()` answers alike on both.
#[cfg(host_fs)]
pub fn read_file_text_into(path: &str, buf: &mut String) {
    buf.clear();
    if let Some(text) = crate::wasm::host_fs_read_text(path) {
        *buf = text;
    }
}

/// Read the entire contents of a file into `content`, replacing its previous value.
/// If the file cannot be opened or read, `content` is cleared.
/// Bytecode equivalent: `State::get_file_text` in `src/state/io.rs`.
#[cfg(not(host_fs))]
pub fn OpGetFileText(cell: &std::cell::UnsafeCell<Stores>, file: DbRef, content: &mut String) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if file.rec == 0 {
        return;
    }
    let file_path = {
        let store = stores.store(&file);
        store
            .get_str(store.get_u32_raw(file.rec, file.pos + 24))
            .to_owned()
    };
    // #255 / @PLN9: re-home against the program anchor (native parity with
    // the interpreter's `State::get_file_text`).
    let file_path = stores.resolve_path(&file_path);
    read_file_text_into(&file_path, content);
}

/// Read the whole file through the host bridge.
#[cfg(host_fs)]
pub fn OpGetFileText(cell: &std::cell::UnsafeCell<Stores>, file: DbRef, content: &mut String) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    content.clear();
    if file.rec == 0 {
        return;
    }
    let path = file_record_path(stores, &file);
    read_file_text_into(&path, content);
}

/// Seek to `pos` bytes from the start of the file.
/// If the file handle is not yet open, stores `pos` in `#next` so the first
/// read/write applies the seek after opening.
/// Bytecode equivalent: `State::seek_file` in `src/state/io.rs`.
#[cfg(not(host_fs))]
pub fn OpSeekFile(cell: &std::cell::UnsafeCell<Stores>, file: DbRef, pos: i64) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if file.rec == 0 {
        return;
    }
    let file_ref = stores.store(&file).get_i32_raw(file.rec, file.pos + 28);
    if file_ref == i32::MIN {
        stores
            .store_mut(&file)
            .set_long(file.rec, file.pos + 16, pos);
    } else if let Some(f) = &mut stores.files[file_ref as usize]
        && let Err(e) = f.seek(SeekFrom::Start(pos as u64))
    {
        crate::loft_eprintln!("file seek error: {e}");
    }
}

/// Seek the host's per-path cursor, and record the position in `#next` so a
/// following read/write starts there.
#[cfg(host_fs)]
pub fn OpSeekFile(cell: &std::cell::UnsafeCell<Stores>, file: DbRef, pos: i64) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if file.rec == 0 {
        return;
    }
    let path = file_record_path(stores, &file);
    crate::wasm::host_fs_seek(&path, pos);
    stores
        .store_mut(&file)
        .set_long(file.rec, file.pos + 16, pos);
}

/// Return the byte size of the file, or `i64::MIN` if the size cannot be determined.
/// Bytecode equivalent: `State::size_file` in `src/state/io.rs`.
#[must_use]
#[cfg(not(host_fs))]
pub fn OpSizeFile(cell: &std::cell::UnsafeCell<Stores>, file: DbRef) -> i64 {
    let stores: &Stores = unsafe { &*cell.get() };
    if file.rec == 0 {
        return i64::MIN;
    }
    let file_path = {
        let store = stores.store(&file);
        store
            .get_str(store.get_u32_raw(file.rec, file.pos + 24))
            .to_owned()
    };
    // #255 / @PLN9: re-home against the program anchor.
    let file_path = stores.resolve_path(&file_path);
    if let Ok(meta) = std::fs::metadata(&file_path) {
        meta.len().cast_signed()
    } else {
        i64::MIN
    }
}

/// Ask the host for the size.  `i64::MIN` when the path is absent — the same
/// sentinel `std::fs::metadata` failing produces, which is what `f#size`
/// answers null on.
#[must_use]
#[cfg(host_fs)]
pub fn OpSizeFile(cell: &std::cell::UnsafeCell<Stores>, file: DbRef) -> i64 {
    let stores: &Stores = unsafe { &*cell.get() };
    if file.rec == 0 {
        return i64::MIN;
    }
    let path = file_record_path(stores, &file);
    let size = crate::wasm::host_fs_file_size(&path);
    if size < 0 { i64::MIN } else { size }
}

/// Truncate (or extend) the file to `size` bytes.  Closes any open handle first.
/// Returns `true` on success, `false` on failure.
/// Bytecode equivalent: `State::truncate_file` in `src/state/io.rs`.
#[cfg(not(host_fs))]
pub fn OpTruncateFile(cell: &std::cell::UnsafeCell<Stores>, file: DbRef, size: i64) -> bool {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if file.rec == 0 {
        return false;
    }
    let file_path = {
        let store = stores.store(&file);
        store
            .get_str(store.get_u32_raw(file.rec, file.pos + 24))
            .to_owned()
    };
    // #255 / @PLN9: re-home against the program anchor.
    let file_path = stores.resolve_path(&file_path);
    // Close any open handle so resize starts from a clean state.
    let file_ref = stores.store(&file).get_i32_raw(file.rec, file.pos + 28);
    if file_ref != i32::MIN && (file_ref as usize) < stores.files.len() {
        stores.files[file_ref as usize] = None;
        stores
            .store_mut(&file)
            .set_i32_raw(file.rec, file.pos + 28, i32::MIN);
        stores
            .store_mut(&file)
            .set_long(file.rec, file.pos + 8, i64::MIN);
        stores
            .store_mut(&file)
            .set_long(file.rec, file.pos + 16, i64::MIN);
    }
    OpenOptions::new()
        .write(true)
        .open(&file_path)
        .and_then(|f| f.set_len(size as u64))
        .is_ok()
}

/// Resize through the host: read, slice or zero-extend, write back.  The host
/// contract has no truncate of its own, and composing it here keeps the page's
/// import list one name shorter (`src/lib.rs`).
#[cfg(host_fs)]
pub fn OpTruncateFile(cell: &std::cell::UnsafeCell<Stores>, file: DbRef, size: i64) -> bool {
    let stores: &Stores = unsafe { &*cell.get() };
    if file.rec == 0 {
        return false;
    }
    let path = file_record_path(stores, &file);
    let Some(mut bytes) = crate::wasm::host_fs_read_binary(&path) else {
        return false;
    };
    let new_len = size.max(0) as usize;
    bytes.resize(new_len, 0);
    crate::wasm::host_fs_write_binary(&path, &bytes) == 0
}

/// Flush buffered bytes for the open handle backing `file` so that
/// preceding writes are durable.  Returns `true` on success.  If the
/// file is not currently open returns `true` — there is nothing to flush.
/// Bytecode equivalent: `State::sync_file` in `src/state/io.rs`.
#[cfg(not(host_fs))]
pub fn OpSyncFile(cell: &std::cell::UnsafeCell<Stores>, file: DbRef) -> bool {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if file.rec == 0 {
        return false;
    }
    let file_ref = stores.store(&file).get_i32_raw(file.rec, file.pos + 28);
    if file_ref != i32::MIN
        && (file_ref as usize) < stores.files.len()
        && let Some(f) = &stores.files[file_ref as usize]
    {
        f.sync_data().is_ok()
    } else {
        true
    }
}

/// A host write lands when the call returns — there is no buffered handle to
/// flush — so a sync succeeds with nothing to do.  It answers `true` for the
/// same reason the native path does when no handle is open: `false` means the
/// bytes did NOT reach the file, and on this target they already have.
#[cfg(host_fs)]
pub fn OpSyncFile(_cell: &std::cell::UnsafeCell<Stores>, file: DbRef) -> bool {
    file.rec != 0
}

// ─── File I/O ─────────────────────────────────────────────────────────────────

/// Open (or reuse) a file handle for writing.  Returns the index into
/// `stores.files`, or `i32::MIN` on error.
///
/// The handle is opened for read+write without truncating so that
/// successive `f += …` appends preserve earlier bytes.  Explicit
/// truncation goes through `OpTruncateFile` (`f.set_file_size(0)`
/// / `f#size = 0`).
#[cfg(not(host_fs))]
fn file_handle_write(stores: &mut Stores, file: &DbRef) -> i32 {
    let f_nr = stores.files.len() as i32;
    let file_ref = stores.store(file).get_i32_raw(file.rec, file.pos + 28);
    if file_ref != i32::MIN {
        return file_ref;
    }
    let (file_name, format) = {
        let store = stores.store(file);
        (
            store
                .get_str(store.get_u32_raw(file.rec, file.pos + 24))
                .to_owned(),
            store.get_byte(file.rec, file.pos + 32, 0),
        )
    };
    // #255 / @PLN9: re-home against the program anchor.
    let file_name = stores.resolve_path(&file_name);
    match OpenOptions::new()
        .read(true)
        .write(true)
        .create(true)
        .truncate(false)
        .open(&file_name)
    {
        Ok(f) => {
            stores
                .store_mut(file)
                .set_i32_raw(file.rec, file.pos + 28, f_nr);
            // If the file was NotExists, mark it as TextFile now that it exists.
            if format == 5 {
                stores
                    .store_mut(file)
                    .set_byte(file.rec, file.pos + 32, 0, 1);
            }
            stores.files.push(Some(f));
            f_nr
        }
        Err(e) => {
            crate::loft_eprintln!("file open error for {file_name:?}: {e}");
            i32::MIN
        }
    }
}

/// Open (or reuse) a file handle for reading, seeking to `initial_pos`.
/// Returns the index into `stores.files`, or `i32::MIN` on error.
#[cfg(not(host_fs))]
fn file_handle_read(stores: &mut Stores, file: &DbRef, initial_pos: i64) -> i32 {
    let f_nr = stores.files.len() as i32;
    let file_ref = stores.store(file).get_i32_raw(file.rec, file.pos + 28);
    if file_ref != i32::MIN {
        return file_ref;
    }
    let file_name = {
        let store = stores.store(file);
        store
            .get_str(store.get_u32_raw(file.rec, file.pos + 24))
            .to_owned()
    };
    // #255 / @PLN9: re-home against the program anchor.
    let file_name = stores.resolve_path(&file_name);
    match OpenOptions::new().read(true).open(&file_name) {
        Ok(mut f) => {
            if initial_pos > 0 {
                let _ = f.seek(SeekFrom::Start(initial_pos as u64));
            }
            stores
                .store_mut(file)
                .set_i32_raw(file.rec, file.pos + 28, f_nr);
            stores.files.push(Some(f));
            f_nr
        }
        Err(e) => {
            crate::loft_eprintln!("file open error for {file_name:?}: {e}");
            i32::MIN
        }
    }
}

/// Trait for types that can be written to / read from a loft binary or text file.
///
/// The `db_tp` parameter is the loft type index stored in `stores.types`; it
/// controls how many bytes are used and the interpretation (integer vs byte vs
/// short vs text, etc.).
pub trait FileVal {
    /// Serialise `self` into bytes that will be appended to the file.
    fn file_to_bytes(&self, stores: &Stores, db_tp: i32, little_endian: bool) -> Vec<u8>;
    /// Deserialise `bytes` (already read from the file) into `self`.
    /// Receives `&mut Stores` so that collection types (e.g. `vector<T>`) can append elements.
    fn file_from_bytes(
        &mut self,
        stores: &mut Stores,
        db_tp: i32,
        little_endian: bool,
        bytes: &[u8],
    );
}

impl FileVal for i32 {
    fn file_to_bytes(&self, stores: &Stores, db_tp: i32, little_endian: bool) -> Vec<u8> {
        let mut out = Vec::new();
        match db_tp {
            0 | 6 => {
                // integer | character — 4 bytes
                let b = if little_endian {
                    self.to_le_bytes()
                } else {
                    self.to_be_bytes()
                };
                out.extend_from_slice(&b);
            }
            4 => out.push(*self as u8), // boolean — 1 byte
            _ => match &stores.types[db_tp as usize].parts {
                crate::database::Parts::Byte(_, _) => out.push(*self as u8),
                crate::database::Parts::Short(_, _) | crate::database::Parts::ShortRaw(_, _) => {
                    let v = *self as i16;
                    let b = if little_endian {
                        v.to_le_bytes()
                    } else {
                        v.to_be_bytes()
                    };
                    out.extend_from_slice(&b);
                }
                _ => {
                    let b = if little_endian {
                        self.to_le_bytes()
                    } else {
                        self.to_be_bytes()
                    };
                    out.extend_from_slice(&b);
                }
            },
        }
        out
    }

    fn file_from_bytes(
        &mut self,
        stores: &mut Stores,
        db_tp: i32,
        little_endian: bool,
        bytes: &[u8],
    ) {
        match db_tp {
            0 | 6 => {
                if bytes.len() >= 4 {
                    *self = if little_endian {
                        i32::from_le_bytes(bytes[..4].try_into().unwrap_or([0; 4]))
                    } else {
                        i32::from_be_bytes(bytes[..4].try_into().unwrap_or([0; 4]))
                    };
                }
            }
            4 => {
                if let Some(&b) = bytes.first() {
                    *self = i32::from(b);
                }
            }
            // @PLN47 W2/W3 — signedness comes from the type's range; see the `i64`
            // impl below for the full note.
            _ => match &stores.types[db_tp as usize].parts {
                crate::database::Parts::Byte(from, _) => {
                    if let Some(&b) = bytes.first() {
                        *self = if *from < 0 {
                            i32::from(b as i8)
                        } else {
                            i32::from(b)
                        };
                    }
                }
                crate::database::Parts::Short(from, _)
                | crate::database::Parts::ShortRaw(from, _) => {
                    if bytes.len() >= 2 {
                        let d: [u8; 2] = bytes[..2].try_into().unwrap_or([0; 2]);
                        *self = match (little_endian, *from < 0) {
                            (true, true) => i32::from(i16::from_le_bytes(d)),
                            (true, false) => i32::from(u16::from_le_bytes(d)),
                            (false, true) => i32::from(i16::from_be_bytes(d)),
                            (false, false) => i32::from(u16::from_be_bytes(d)),
                        };
                    }
                }
                _ => {
                    if bytes.len() >= 4 {
                        *self = if little_endian {
                            i32::from_le_bytes(bytes[..4].try_into().unwrap_or([0; 4]))
                        } else {
                            i32::from_be_bytes(bytes[..4].try_into().unwrap_or([0; 4]))
                        };
                    }
                }
            },
        }
    }
}

impl FileVal for i64 {
    fn file_to_bytes(&self, stores: &Stores, db_tp: i32, little_endian: bool) -> Vec<u8> {
        // Post-2c: `integer` is i64 on the loft stack, but file-width is
        // still declared per field type — u8 writes 1 byte, u16 writes 2,
        // i32 writes 4, long writes 8.  Dispatch on `db_tp` mirroring the
        // `FileVal for i32` impl so narrow-typed writes emit the right
        // byte count and the final file size matches the interpreter.
        let mut out = Vec::new();
        match db_tp {
            0 | 1 => {
                // integer | long — both 8 bytes post-2c.
                let b = if little_endian {
                    self.to_le_bytes()
                } else {
                    self.to_be_bytes()
                };
                out.extend_from_slice(&b);
            }
            6 => {
                // character — 4-byte narrow (u32 code point).
                let v = *self as u32;
                let b = if little_endian {
                    v.to_le_bytes()
                } else {
                    v.to_be_bytes()
                };
                out.extend_from_slice(&b);
            }
            4 => out.push(*self as u8), // boolean
            _ => match &stores.types[db_tp as usize].parts {
                crate::database::Parts::Byte(_, _) => out.push(*self as u8),
                crate::database::Parts::Short(_, _) | crate::database::Parts::ShortRaw(_, _) => {
                    let v = *self as i16;
                    let b = if little_endian {
                        v.to_le_bytes()
                    } else {
                        v.to_be_bytes()
                    };
                    out.extend_from_slice(&b);
                }
                crate::database::Parts::Int(_, _) => {
                    let v = *self as i32;
                    let b = if little_endian {
                        v.to_le_bytes()
                    } else {
                        v.to_be_bytes()
                    };
                    out.extend_from_slice(&b);
                }
                _ => {
                    let b = if little_endian {
                        self.to_le_bytes()
                    } else {
                        self.to_be_bytes()
                    };
                    out.extend_from_slice(&b);
                }
            },
        }
        out
    }
    fn file_from_bytes(
        &mut self,
        stores: &mut Stores,
        db_tp: i32,
        little_endian: bool,
        bytes: &[u8],
    ) {
        match db_tp {
            0 | 1 => {
                if bytes.len() >= 8 {
                    *self = if little_endian {
                        i64::from_le_bytes(bytes[..8].try_into().unwrap_or([0; 8]))
                    } else {
                        i64::from_be_bytes(bytes[..8].try_into().unwrap_or([0; 8]))
                    };
                }
            }
            6 => {
                if bytes.len() >= 4 {
                    *self = i64::from(if little_endian {
                        u32::from_le_bytes(bytes[..4].try_into().unwrap_or([0; 4]))
                    } else {
                        u32::from_be_bytes(bytes[..4].try_into().unwrap_or([0; 4]))
                    });
                }
            }
            4 => {
                if let Some(&b) = bytes.first() {
                    *self = i64::from(b);
                }
            }
            // @PLN47 W2/W3 — the SIGN of a narrow read comes from the type's own
            // range: `i8`/`i16` (range `from` negative) sign-extend, `u8`/`u16`
            // (`from >= 0`) zero-extend.  Reading unconditionally as `i8`/`i16`
            // only landed on the right value because a downstream `as u8`/`as u16`
            // re-narrowed it; a `u16` 0xBEEF delivered here as -16657 the moment
            // nothing did (loft#624 follow-up).  Same rule as the interpreter's
            // `State::dispatch_read_data`, so the two backends agree by
            // construction rather than by a consumer's cast.
            _ => match &stores.types[db_tp as usize].parts {
                crate::database::Parts::Byte(from, _) => {
                    if let Some(&b) = bytes.first() {
                        *self = if *from < 0 {
                            i64::from(b as i8)
                        } else {
                            i64::from(b)
                        };
                    }
                }
                crate::database::Parts::Short(from, _)
                | crate::database::Parts::ShortRaw(from, _) => {
                    if bytes.len() >= 2 {
                        let d: [u8; 2] = bytes[..2].try_into().unwrap_or([0; 2]);
                        *self = match (little_endian, *from < 0) {
                            (true, true) => i64::from(i16::from_le_bytes(d)),
                            (true, false) => i64::from(u16::from_le_bytes(d)),
                            (false, true) => i64::from(i16::from_be_bytes(d)),
                            (false, false) => i64::from(u16::from_be_bytes(d)),
                        };
                    }
                }
                crate::database::Parts::Int(_, _) => {
                    if bytes.len() >= 4 {
                        *self = i64::from(if little_endian {
                            i32::from_le_bytes(bytes[..4].try_into().unwrap_or([0; 4]))
                        } else {
                            i32::from_be_bytes(bytes[..4].try_into().unwrap_or([0; 4]))
                        });
                    }
                }
                _ => {
                    if bytes.len() >= 8 {
                        *self = if little_endian {
                            i64::from_le_bytes(bytes[..8].try_into().unwrap_or([0; 8]))
                        } else {
                            i64::from_be_bytes(bytes[..8].try_into().unwrap_or([0; 8]))
                        };
                    }
                }
            },
        }
    }
}

impl FileVal for f32 {
    fn file_to_bytes(&self, _stores: &Stores, _db_tp: i32, little_endian: bool) -> Vec<u8> {
        if little_endian {
            self.to_le_bytes().to_vec()
        } else {
            self.to_be_bytes().to_vec()
        }
    }
    fn file_from_bytes(
        &mut self,
        _stores: &mut Stores,
        _db_tp: i32,
        little_endian: bool,
        bytes: &[u8],
    ) {
        if bytes.len() >= 4 {
            *self = if little_endian {
                f32::from_le_bytes(bytes[..4].try_into().unwrap_or([0; 4]))
            } else {
                f32::from_be_bytes(bytes[..4].try_into().unwrap_or([0; 4]))
            };
        }
    }
}

impl FileVal for f64 {
    fn file_to_bytes(&self, _stores: &Stores, _db_tp: i32, little_endian: bool) -> Vec<u8> {
        if little_endian {
            self.to_le_bytes().to_vec()
        } else {
            self.to_be_bytes().to_vec()
        }
    }
    fn file_from_bytes(
        &mut self,
        _stores: &mut Stores,
        _db_tp: i32,
        little_endian: bool,
        bytes: &[u8],
    ) {
        if bytes.len() >= 8 {
            *self = if little_endian {
                f64::from_le_bytes(bytes[..8].try_into().unwrap_or([0; 8]))
            } else {
                f64::from_be_bytes(bytes[..8].try_into().unwrap_or([0; 8]))
            };
        }
    }
}

impl FileVal for u8 {
    /// `boolean` is the only loft scalar that lowers to a native `u8` for
    /// binary I/O (@PLN47 W3); it is always a single byte — `0`/`1`, or the
    /// `255` tri-state null sentinel.  Endianness and `db_tp` are irrelevant
    /// for a one-byte value.
    fn file_to_bytes(&self, _stores: &Stores, _db_tp: i32, _little_endian: bool) -> Vec<u8> {
        vec![*self]
    }
    fn file_from_bytes(
        &mut self,
        _stores: &mut Stores,
        _db_tp: i32,
        _little_endian: bool,
        bytes: &[u8],
    ) {
        if let Some(&b) = bytes.first() {
            *self = b;
        }
    }
}

impl FileVal for String {
    fn file_to_bytes(&self, _stores: &Stores, _db_tp: i32, _little_endian: bool) -> Vec<u8> {
        self.as_bytes().to_vec()
    }
    fn file_from_bytes(
        &mut self,
        _stores: &mut Stores,
        _db_tp: i32,
        _little_endian: bool,
        bytes: &[u8],
    ) {
        *self = String::from_utf8_lossy(bytes).into_owned();
    }
}

impl FileVal for DbRef {
    /// Serialise a vector (or struct/simple) `DbRef` into bytes for binary file output.
    ///
    /// For `Parts::Vector(elem_tp)` the method iterates every element and delegates to
    /// `Stores::read_data`; for all other types it calls `read_data` on `self` directly.
    fn file_to_bytes(&self, stores: &Stores, db_tp: i32, little_endian: bool) -> Vec<u8> {
        use crate::database::Parts;
        let mut data = Vec::new();
        if let Some(tp_info) = stores.types.get(db_tp as usize) {
            if let Parts::Vector(elem_tp) = tp_info.parts {
                let store = &stores.allocations[self.store_nr as usize];
                let v_rec = store.get_u32_raw(self.rec, self.pos);
                if v_rec != 0 {
                    let length = store.get_u32_raw(v_rec, 4);
                    let elem_size = u32::from(stores.size(elem_tp));
                    for i in 0..length {
                        let elem = DbRef {
                            store_nr: self.store_nr,
                            rec: v_rec,
                            pos: 8 + elem_size * i,
                        };
                        stores.read_data(&elem, elem_tp, little_endian, &mut data);
                    }
                }
            } else {
                stores.read_data(self, db_tp as u16, little_endian, &mut data);
            }
        }
        data
    }

    fn file_from_bytes(
        &mut self,
        stores: &mut Stores,
        db_tp: i32,
        little_endian: bool,
        bytes: &[u8],
    ) {
        use crate::database::Parts;
        if let Some(tp_info) = stores.types.get(db_tp as usize) {
            if let Parts::Vector(elem_tp) = tp_info.parts.clone() {
                let elem_size = u32::from(stores.size(elem_tp));
                if elem_size == 0 || bytes.is_empty() {
                    return;
                }
                // The generated code initialises the destination as a null sentinel
                // (store_nr=u16::MAX, rec=0).  Allocate a real store before the first
                // vector_append, which indexes stores[store_nr] and would panic on u16::MAX.
                if self.rec == 0 {
                    *self = stores.database(12);
                    // Zero-init the vector header slot so vector_append sees
                    // vec_rec=0 (no storage yet) instead of garbage memory.
                    stores.store_mut(self).set_u32_raw(self.rec, self.pos, 0);
                }
                let n_elems = bytes.len() / elem_size as usize;
                for i in 0..n_elems {
                    let slice = &bytes[i * elem_size as usize..(i + 1) * elem_size as usize];
                    let elem_ref =
                        crate::vector::vector_append(self, elem_size, &mut stores.allocations);
                    stores.write_data(&elem_ref, elem_tp, little_endian, slice);
                    crate::vector::vector_finish(self, &mut stores.allocations);
                }
            } else {
                stores.write_data(self, db_tp as u16, little_endian, bytes);
            }
        }
    }
}

/// Write a value to a loft `File` record.
/// Bytecode equivalent: `State::write_file` in `src/state/io.rs`.
#[cfg(not(host_fs))]
pub fn OpWriteFile<T: FileVal>(
    cell: &std::cell::UnsafeCell<Stores>,
    file: DbRef,
    val: &mut T,
    db_tp: i32,
) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if file.rec == 0 {
        return;
    }
    let format = stores.store(&file).get_byte(file.rec, file.pos + 32, 0);
    // format: 1=TextFile, 2=LittleEndian, 3=BigEndian, 5=NotExists
    if format != 1 && format != 2 && format != 3 && format != 5 {
        return;
    }
    let little_endian = format == 2;
    let file_ref = file_handle_write(stores, &file);
    if file_ref == i32::MIN {
        return;
    }
    // Track write position: set #index = where this write starts.
    // `+=` is append-only: when the user has not explicitly set
    // `f#next = N`, the default position is the current end of file
    // (consistent with `vector += [elem]` / `text += "more"`).
    let raw_next = stores.store(&file).get_long(file.rec, file.pos + 16);
    let next_pos = if raw_next == i64::MIN {
        if let Some(f) = stores
            .files
            .get_mut(file_ref as usize)
            .and_then(|x| x.as_mut())
        {
            f.seek(SeekFrom::End(0)).unwrap_or(0) as i64
        } else {
            0
        }
    } else {
        if let Some(f) = stores
            .files
            .get_mut(file_ref as usize)
            .and_then(|x| x.as_mut())
        {
            let _ = f.seek(SeekFrom::Start(raw_next as u64));
        }
        raw_next
    };
    stores
        .store_mut(&file)
        .set_long(file.rec, file.pos + 8, next_pos);
    let data = val.file_to_bytes(stores, db_tp, little_endian);
    let written = data.len() as i64;
    if let Some(f) = stores
        .files
        .get_mut(file_ref as usize)
        .and_then(|x| x.as_mut())
        && let Err(e) = f.write_all(&data)
    {
        crate::loft_eprintln!("file write error: {e}");
    }
    // Update #next to reflect the end of this write.
    stores
        .store_mut(&file)
        .set_long(file.rec, file.pos + 16, next_pos + written);
}

/// Write through the host bridge at the position `#next` names.
#[cfg(host_fs)]
pub fn OpWriteFile<T: FileVal>(
    cell: &std::cell::UnsafeCell<Stores>,
    file: DbRef,
    val: &mut T,
    db_tp: i32,
) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if file.rec == 0 {
        return;
    }
    let format = stores.store(&file).get_byte(file.rec, file.pos + 32, 0);
    // format: 1=TextFile, 2=LittleEndian, 3=BigEndian, 5=NotExists
    if format != 1 && format != 2 && format != 3 && format != 5 {
        return;
    }
    let little_endian = format == 2;
    let path = file_record_path(stores, &file);
    // `+=` is append-only unless the user set `f#next = N`: with no explicit
    // position the write starts at the current end of file, which here is what
    // the host reports rather than what an open handle's cursor says.  A path
    // the host does not have yet reports -1 and starts at 0.
    let raw_next = stores.store(&file).get_long(file.rec, file.pos + 16);
    let next_pos = if raw_next == i64::MIN {
        crate::wasm::host_fs_file_size(&path).max(0)
    } else {
        raw_next
    };
    stores
        .store_mut(&file)
        .set_long(file.rec, file.pos + 8, next_pos);
    let data = val.file_to_bytes(stores, db_tp, little_endian);
    let written = data.len() as i64;
    crate::wasm::host_fs_seek(&path, next_pos);
    crate::wasm::host_fs_write_bytes(&path, &data);
    stores
        .store_mut(&file)
        .set_long(file.rec, file.pos + 16, next_pos + written);
}

/// Read bytes from a loft `File` record into `val`.
/// Bytecode equivalent: `State::read_file` in `src/state/io.rs`.
#[cfg(not(host_fs))]
pub fn OpReadFile<T: FileVal>(
    cell: &std::cell::UnsafeCell<Stores>,
    file: DbRef,
    val: &mut T,
    bytes: i64,
    db_tp: i32,
) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if file.rec == 0 {
        return;
    }
    let format = stores.store(&file).get_byte(file.rec, file.pos + 32, 0);
    if format != 1 && format != 2 && format != 3 && format != 5 {
        return;
    }
    let little_endian = format == 2;
    // Track read position: #next holds the byte offset to read from.
    let raw_next = stores.store(&file).get_long(file.rec, file.pos + 16);
    let next_pos = if raw_next == i64::MIN { 0 } else { raw_next };
    stores
        .store_mut(&file)
        .set_long(file.rec, file.pos + 8, next_pos);
    let file_ref = file_handle_read(stores, &file, next_pos);
    if file_ref == i32::MIN {
        return;
    }
    let n = bytes.max(0) as usize;
    let mut buf = vec![0u8; n];
    let is_text = stores.is_text_type(db_tp as u16);
    let nread = if let Some(f) = stores
        .files
        .get_mut(file_ref as usize)
        .and_then(|x| x.as_mut())
    {
        if is_text {
            f.read(&mut buf).unwrap_or(0)
        } else if f.read_exact(&mut buf).is_ok() {
            n
        } else {
            0
        }
    } else {
        0
    };
    buf.truncate(nread);
    val.file_from_bytes(stores, db_tp, little_endian, &buf);
    stores
        .store_mut(&file)
        .set_long(file.rec, file.pos + 16, next_pos + nread as i64);
}

/// Read through the host bridge from the position `#next` names.
#[cfg(host_fs)]
pub fn OpReadFile<T: FileVal>(
    cell: &std::cell::UnsafeCell<Stores>,
    file: DbRef,
    val: &mut T,
    bytes: i64,
    db_tp: i32,
) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if file.rec == 0 {
        return;
    }
    let format = stores.store(&file).get_byte(file.rec, file.pos + 32, 0);
    if format != 1 && format != 2 && format != 3 && format != 5 {
        return;
    }
    let little_endian = format == 2;
    let raw_next = stores.store(&file).get_long(file.rec, file.pos + 16);
    let next_pos = if raw_next == i64::MIN { 0 } else { raw_next };
    stores
        .store_mut(&file)
        .set_long(file.rec, file.pos + 8, next_pos);
    let path = file_record_path(stores, &file);
    let n = bytes.max(0) as usize;
    crate::wasm::host_fs_seek(&path, next_pos);
    // A read past the end answers FEWER bytes, and `#next` must advance by what
    // actually arrived — advancing by the requested `n` would walk the cursor
    // past the file and make every following read empty.
    if let Some(data) = crate::wasm::host_fs_read_bytes(&path, n) {
        let actual = data.len() as i64;
        val.file_from_bytes(stores, db_tp, little_endian, &data);
        stores
            .store_mut(&file)
            .set_long(file.rec, file.pos + 16, next_pos + actual);
    }
}

/// Trait allowing `OpRemove` to work with both plain-vector (`i32` index) and
/// sorted/tree (`i64` packed iterator) state variables.
pub trait IterState {
    fn get_cur(&self) -> i32;
    fn set_cur(&mut self, n: i32);
    fn get_finish(&self) -> u32 {
        u32::MAX
    }
    fn set_finish(&mut self, _n: u32) {}
    /// Plain-vector iteration: the whole state is a signed i64
    /// counter (no packed finish-field semantics).  Default
    /// implementation truncates to i32 and delegates to `set_cur`,
    /// which is correct for the i32 impl.  The i64 impl overrides
    /// to write the full 64-bit value — otherwise `set_cur(-1)`
    /// would zero-extend 0xFFFFFFFF, which the generated loop then
    /// treats as 4_294_967_295 and skips past the end of the
    /// vector instead of decrementing to -1.
    fn set_cur_i64_plain(&mut self, n: i64) {
        self.set_cur(n as i32);
    }
    /// Plain-vector: read as i64 (sign-extends for i32 impl, raw for
    /// i64 impl).  Used by `OpRemove` when `on = 0`.
    fn get_cur_i64_plain(&self) -> i64 {
        i64::from(self.get_cur())
    }
}

impl IterState for i32 {
    fn get_cur(&self) -> i32 {
        *self
    }
    fn set_cur(&mut self, n: i32) {
        *self = n;
    }
}

impl IterState for i64 {
    fn get_cur(&self) -> i32 {
        ((*self as u64) as u32).cast_signed()
    }
    fn set_cur(&mut self, n: i32) {
        let finish = (*self as u64) >> 32;
        *self = ((finish << 32) | u64::from(n as u32)).cast_signed();
    }
    fn get_finish(&self) -> u32 {
        ((*self as u64) >> 32) as u32
    }
    fn set_finish(&mut self, n: u32) {
        let cur = (*self as u64) as u32;
        *self = ((u64::from(n) << 32) | u64::from(cur)).cast_signed();
    }
    fn set_cur_i64_plain(&mut self, n: i64) {
        *self = n;
    }
    fn get_cur_i64_plain(&self) -> i64 {
        *self
    }
}

/// Remove the element at the current iterator position and update the iterator
/// so the next step visits the correct successor.
///
/// - `on & 63 == 0`: plain vector — `arg` is the element type index; size is
///   looked up via `stores.get_type(arg as u16).size`.
/// - `on & 63 == 2`: sorted vector — `arg` is the element size in bytes directly.
///
/// Bytecode equivalent: `State::remove` in `src/state/io.rs`.
///
/// # Panics
/// Panics if `data.store_nr == u16::MAX` (coroutine `DbRef`) — the compiler is
/// expected to reject `e#remove` on generator iterators before this is reached.
pub fn OpRemove<S: IterState>(
    cell: &std::cell::UnsafeCell<Stores>,
    state: &mut S,
    data: DbRef,
    on: i32,
    arg: i32,
) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    // Defense-in-depth: coroutine DbRefs (store_nr == u16::MAX) must not reach remove().
    // The compiler already rejects e#remove on generator iterators (CO1.5c / S24).
    assert!(
        data.store_nr != u16::MAX,
        "e#remove on coroutine DbRef — compiler check should have rejected this"
    );
    if data.store_nr == u16::MAX {
        return;
    }
    let cur = state.get_cur();
    let reverse = (on & 64) != 0;
    match on & 63 {
        0 => {
            // vector / array: `arg` is the element type index, and
            // `remove_vector_at` reads the layout off it.
            // Use the i64-plain accessors so the generated code, which
            // drives `var_INDEX` as a raw i64 counter (`var += 1`),
            // sees a properly sign-extended value after `set_cur(-1)`.
            let cur_i64 = state.get_cur_i64_plain();
            // Direction decides the rewind — see the twin in `State::remove`
            // (`src/state/io.rs`), and keep the two in step.
            let n = if reverse { cur_i64 } else { cur_i64 - 1 };
            stores.remove_vector_at(&data, arg as u16, cur_i64);
            state.set_cur_i64_plain(n);
        }
        1 => {
            // index (red-black tree): arg is the type index; fields offset derived from it
            let cur_u = cur as u32;
            if cur_u == u32::MAX {
                return;
            }
            let tp = arg as u16;
            // The removal and the cursor it leaves behind are one decision, shared with the
            // interpreter (loft#1272).
            match stores.remove_during_tree_iteration(&data, tp, cur_u, state.get_finish(), reverse)
            {
                // Nothing follows in range: signal end-of-iteration.
                None => state.set_finish(u32::MAX),
                // Park at the predecessor so the next OpStep visits what followed.
                Some(pred) => state.set_cur(pred.cast_signed()),
            }
        }
        2 => {
            // sorted: inline elements, `arg` is the element type; `cur` is an index
            if cur < 0 {
                return;
            }
            let n = if reverse { cur } else { cur - 1 };
            stores.remove_vector_at(&data, arg as u16, i64::from(cur));
            state.set_cur(n);
        }
        3 => {
            // ordered: 4-byte record-id slots, `arg` is the element type; `cur` is a
            // BYTE offset into the slot vector (8, 12, ...).  Without this arm the
            // native backend silently removed NOTHING while the interpreter removed
            // correctly — one `e#remove` spelling, two answers (loft#903).
            if cur < 8 {
                return;
            }
            // Same rewind rule as arm 0 — see the twin in `State::remove`
            // (`src/state/io.rs`), and keep the two in step.
            let n = if reverse { cur } else { cur - 4 };
            stores.remove_vector_at(&data, arg as u16, i64::from((cur - 8) / 4));
            state.set_cur(n);
        }
        _ => {}
    }
}

/// Remove a record from a hash or index collection.
///
/// `tp`'s `0x8000` bit says UNLINK ONLY: the member is one a linked group's
/// removal passes through on its way to the one that frees (loft#900).
///
/// Bytecode equivalent: `State::hash_remove` in `src/state/io.rs`.
pub fn OpHashRemove(cell: &std::cell::UnsafeCell<Stores>, data: DbRef, rec: DbRef, tp: i32) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let raw = tp as u16;
    if rec.rec != 0 {
        if raw & crate::database::CLEAR_KEYED_VIEW == 0 {
            stores.remove_owned(&data, &rec, raw);
        } else {
            stores.remove(&data, &rec, raw & !crate::database::CLEAR_KEYED_VIEW);
        }
    }
}

/// Append `count - 1` copies of the last element of `data`, expanding the vector.
///
/// Bytecode equivalent: `State::append_copy` in `src/state/io.rs`.
pub fn OpAppendCopy(cell: &std::cell::UnsafeCell<Stores>, data: DbRef, count: i64, tp: i32) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let ctp = stores.content(tp as u16);
    let size = u32::from(stores.size(ctp));
    let length = vector::length_vector(&data, &stores.allocations);
    // A count is a TOTAL; a negative one is no vector at all, so it answers the same as
    // zero. Twin of `State::append_copy` (`src/state/io.rs`) — keep the two in step.
    let multiply = count.clamp(0, i64::from(u32::MAX)) as u32;
    // `[x; n]` asks for n elements TOTAL and the template is already appended, so `n - 1`
    // more are needed. `n == 0` drops the template too, and must return before the
    // `multiply - 1` below: that subtraction is on a `u32`, so zero underflows into
    // ~4.3 billion `copy_block`s that walk off the end of the store.
    // Twin of `State::append_copy` (`src/state/io.rs`) — keep the two in step.
    if multiply == 0 {
        let store = crate::keys::mut_store(&data, &mut stores.allocations);
        let vec_rec = store.get_u32_raw(data.rec, data.pos);
        let len_now = store.get_u32_raw(vec_rec, 4);
        store.set_u32_raw(vec_rec, 4, len_now.saturating_sub(1));
        return;
    }
    let extra = multiply - 1;
    if extra == 0 {
        return; // the template alone already IS the answer
    }
    // Resize to accommodate `extra` additional elements.
    vector::vector_append(&data, size, &mut stores.allocations);
    stores.vector_set_size(&data, extra, size);
    // Re-read the backing record AFTER the resize: growing the vector can move it, and
    // BOTH ends of the copy live inside it. Only the destination was re-read here, so
    // the template `from` still named the record's old home.
    let v_rec = crate::keys::store(&data, &stores.allocations).get_u32_raw(data.rec, data.pos);
    let from = DbRef {
        store_nr: data.store_nr,
        rec: v_rec,
        pos: 8 + (length * size - size),
    };
    for i in 0..extra {
        let to = DbRef {
            store_nr: data.store_nr,
            rec: v_rec,
            pos: 8 + (length + i) * size,
        };
        stores.copy_block(&from, &to, size);
        // The claim source is the TEMPLATE element, not the vector handle — see the
        // twin in `State::append_copy`.
        stores.copy_claims(&from, &to, ctp);
    }
}

// @PLAN12 phase 3.5a (2026-05-24) — cr_rand_seed / cr_rand_int /
// the `external::` module that wrapped them all removed.  random's
// drain to lib/random/native/ + the loft::native_call codegen
// helpers mean the cdylib is the single source of RNG state for
// both backends.  Nothing else in the loft crate referenced these
// helpers (greps were empty), so they're safe to delete.

/// Parse a `LOFT_FAKE_*` env var into an `i64`.  See the same-named
/// helper in `src/native.rs` for the full contract; duplicated here so
/// `--native`-compiled binaries honour the override the same way the
/// interpreter does.
#[cfg(any(not(target_arch = "wasm32"), target_os = "wasi"))]
fn fake_clock_env(var: &str) -> Option<i64> {
    std::env::var(var).ok()?.parse::<i64>().ok()
}

/// Return milliseconds since the Unix epoch (1970-01-01T00:00:00 UTC).
/// Returns `i64::MIN` (null) if the system clock reports a time before the epoch.
/// Honours `LOFT_FAKE_NOW_MS` when set (deterministic snapshot tests).
/// Bytecode equivalent: `n_now` in `src/native.rs`.
///
/// Plan 09 phase 01 step 1.5: migrated to the no-stores ABI
/// (`Abi::None`).  Body doesn't touch `Stores` — wall-clock read only.
/// #620 — `wasm32-wasip2` (`--native-wasm`) reaches this arm too.  WASI exposes
/// a real clock through `wasi:clocks`, which `std`'s `SystemTime` already uses,
/// so it takes the ordinary host path rather than the browser fallback below.
#[cfg(any(not(target_arch = "wasm32"), target_os = "wasi"))]
pub fn n_now() -> i64 {
    if let Some(fake) = fake_clock_env("LOFT_FAKE_NOW_MS") {
        return fake;
    }
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(i64::MIN, |d| d.as_millis() as i64)
}

/// Bytecode equivalent: `n_now` in `src/native.rs`.
#[cfg(all(target_arch = "wasm32", not(target_os = "wasi"), feature = "wasm"))]
pub fn n_now() -> i64 {
    crate::wasm::host_time_now()
}

/// Fallback for the `--html` build (`wasm32-unknown-unknown`, no `wasm`
/// feature): returns 0 because no host time bridge exists.  Mirror of the
/// `n_ticks` fallback below for the same target.
///
/// #620 — this used to be gated on `target_arch = "wasm32"` alone, which also
/// caught `wasm32-wasip2` (`--native-wasm`).  That target HAS a working clock,
/// so the stub was overriding a real reading with 0 rather than standing in for
/// a missing bridge; `not(target_os = "wasi")` narrows it to the browser build
/// the comment always described.
#[cfg(all(target_arch = "wasm32", not(target_os = "wasi"), not(feature = "wasm")))]
pub fn n_now() -> i64 {
    crate::loft_host_time_now_ms() as i64
}

/// Return microseconds elapsed since program start (monotonic clock).
/// Use for frame timing and benchmarks; unaffected by wall-clock adjustments.
/// Honours `LOFT_FAKE_TICKS_US` when set (deterministic snapshot tests).
/// Bytecode equivalent: `n_ticks` in `src/native.rs`.
/// #620 — see [`n_now`]: `wasm32-wasip2` has a real monotonic clock behind
/// `std::time::Instant`, so it shares the host path.
#[cfg(any(not(target_arch = "wasm32"), target_os = "wasi"))]
pub fn n_ticks(cell: &std::cell::UnsafeCell<Stores>) -> i64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if let Some(fake) = fake_clock_env("LOFT_FAKE_TICKS_US") {
        return fake;
    }
    stores.start_time.elapsed().as_micros() as i64
}

/// Bytecode equivalent: `n_ticks` in `src/native.rs`.  Gated on
/// target_arch, not the `wasm` feature — the `--html` build (wasm32,
/// no `wasm` feature) returns 0 because no host time bridge exists.
#[cfg(all(target_arch = "wasm32", not(target_os = "wasi"), feature = "wasm"))]
pub fn n_ticks(cell: &std::cell::UnsafeCell<Stores>) -> i64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    (crate::wasm::host_time_ticks() - stores.start_time_ms) * 1000
}

/// #620 — browser arm; `wasm32-wasip2` uses the real clock above.  Reads the
/// host's `performance.now()`, already monotonic and page-relative, so unlike
/// the `wasm`-feature arm it needs no `start_time_ms` subtraction.
#[cfg(all(target_arch = "wasm32", not(target_os = "wasi"), not(feature = "wasm")))]
pub fn n_ticks(_cell: &std::cell::UnsafeCell<Stores>) -> i64 {
    crate::loft_host_time_ticks_us() as i64
}

