/// P268 — JsonValue.field(name) native wrapper.  JObject linear-scan
/// indexer; returns the value's DbRef, or the shared JNull sentinel
/// for a missing key / non-JObject receiver.  Mirrors the interp
/// `n_field` body in `src/native.rs`.
#[allow(clippy::missing_panics_doc)] // try_from is on a non-negative loop counter
pub fn t_9JsonValue_field(
    cell: &std::cell::UnsafeCell<Stores>,
    self_ref: DbRef,
    name: &str,
) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores
        .store(&self_ref)
        .get_byte(self_ref.rec, self_ref.pos, 0);
    if discr != crate::native::JV_DISCR_OBJECT {
        return crate::native::jv_null_sentinel(stores);
    }
    let obj_tp = stores.name("JObject");
    let fields_pos = u32::from(stores.position(obj_tp, "fields")) + self_ref.pos;
    let fields_rec = stores
        .store(&self_ref)
        .get_i32_raw(self_ref.rec, fields_pos);
    if fields_rec <= 0 {
        return crate::native::jv_null_sentinel(stores);
    }
    let length = i64::from(stores.store(&self_ref).get_u32_raw(fields_rec as u32, 4));
    let jf_tp = stores.name("JsonField");
    let jf_size = u32::from(stores.size(jf_tp));
    let name_field_pos = u32::from(stores.position(jf_tp, "name"));
    let value_field_pos = u32::from(stores.position(jf_tp, "value"));
    for i in 0..length {
        let elm_offset = 8u32 + u32::try_from(i).expect("non-negative length") * jf_size;
        let name_rec = stores
            .store(&self_ref)
            .get_u32_raw(fields_rec as u32, elm_offset + name_field_pos);
        let stored_name = stores.store(&self_ref).get_str(name_rec).to_owned();
        if stored_name == name {
            return DbRef {
                store_nr: self_ref.store_nr,
                rec: fields_rec as u32,
                pos: elm_offset + value_field_pos,
            };
        }
    }
    crate::native::jv_null_sentinel(stores)
}

/// P268 — JsonValue.item(index) native wrapper.  JArray indexer.
/// Returns the element's DbRef or JNull sentinel.  Mirrors interp
/// `n_item`.
#[allow(clippy::missing_panics_doc)] // try_from is on a bounds-checked non-negative index
pub fn t_9JsonValue_item(
    cell: &std::cell::UnsafeCell<Stores>,
    self_ref: DbRef,
    index: i64,
) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let index = index as i32;
    let discr = stores
        .store(&self_ref)
        .get_byte(self_ref.rec, self_ref.pos, 0);
    if discr != crate::native::JV_DISCR_ARRAY || index < 0 {
        return crate::native::jv_null_sentinel(stores);
    }
    let array_tp = stores.name("JArray");
    let items_pos = u32::from(stores.position(array_tp, "items")) + self_ref.pos;
    let items_rec = stores.store(&self_ref).get_i32_raw(self_ref.rec, items_pos);
    if items_rec <= 0 {
        return crate::native::jv_null_sentinel(stores);
    }
    let length = stores.store(&self_ref).get_u32_raw(items_rec as u32, 4) as i32;
    if index >= length {
        return crate::native::jv_null_sentinel(stores);
    }
    let jv_tp = stores.name("JsonValue");
    let jv_size = u32::from(stores.size(jv_tp));
    let elm_offset =
        8u32 + u32::try_from(index).expect("non-negative index checked above") * jv_size;
    DbRef {
        store_nr: self_ref.store_nr,
        rec: items_rec as u32,
        pos: elm_offset,
    }
}

/// P268 — JsonValue.len() native wrapper.  Length of JArray's items
/// or JObject's fields; `i64::MIN` (null) for primitive variants.
/// Mirrors interp `n_len`.
pub fn t_9JsonValue_len(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> i64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    match discr {
        x if x == crate::native::JV_DISCR_ARRAY => {
            let array_tp = stores.name("JArray");
            let items_pos = u32::from(stores.position(array_tp, "items")) + v.pos;
            let items_rec = stores.store(&v).get_i32_raw(v.rec, items_pos);
            if items_rec <= 0 {
                0
            } else {
                i64::from(stores.store(&v).get_u32_raw(items_rec as u32, 4))
            }
        }
        x if x == crate::native::JV_DISCR_OBJECT => {
            let obj_tp = stores.name("JObject");
            let fields_pos = u32::from(stores.position(obj_tp, "fields")) + v.pos;
            let fields_rec = stores.store(&v).get_i32_raw(v.rec, fields_pos);
            if fields_rec <= 0 {
                0
            } else {
                i64::from(stores.store(&v).get_u32_raw(fields_rec as u32, 4))
            }
        }
        _ => i64::MIN,
    }
}

/// P268 — JsonValue.as_text() native wrapper.  Returns the JString
/// payload, or the empty-string null sentinel for any other variant.
/// Mirrors interp `n_as_text`.
#[allow(clippy::missing_panics_doc)] // scratch.last().unwrap() — we just pushed
// @PLN10 — owned `String` (no scratch).  Null is carried as
// `STRING_NULL.to_string()` (the `"\0"` sentinel) — native text-null IS an owned
// `String` value, so `j.as_text() ?? x` / `if !j.as_text()` semantics are
// preserved.  Inline (matching name + cell ABI), so no `native_returns_owned_string`
// entry is needed (cf. `kind` / `to_json`).
pub fn t_9JsonValue_as_text(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> String {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    if discr == crate::native::JV_DISCR_STRING {
        let str_tp = stores.name("JString");
        let value_pos = u32::from(stores.position(str_tp, "value")) + v.pos;
        let s_rec = stores.store(&v).get_u32_raw(v.rec, value_pos);
        stores.store(&v).get_str(s_rec).to_string()
    } else {
        crate::state::STRING_NULL.to_string()
    }
}

/// P268 — JsonValue.as_long() native wrapper.  Truncates the JNumber
/// payload toward zero; returns `i64::MIN` (null) for any other
/// variant.  Mirrors interp `n_as_long`.
pub fn t_9JsonValue_as_long(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> i64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    // @PLN109 — a JInteger reads its EXACT i64 (H5); a JNumber truncates.
    if discr == crate::native::JV_DISCR_INT {
        let int_tp = stores.name("JInteger");
        let value_pos = u32::from(stores.position(int_tp, "value")) + v.pos;
        stores.store(&v).get_int(v.rec, value_pos)
    } else if discr == crate::native::JV_DISCR_NUMBER {
        let num_tp = stores.name("JNumber");
        let value_pos = u32::from(stores.position(num_tp, "value")) + v.pos;
        let n = stores.store(&v).get_float(v.rec, value_pos);
        n.trunc() as i64
    } else {
        i64::MIN
    }
}

/// P268 — JsonValue.kind() native wrapper.  Returns the variant
/// name as a Str: "JNull" / "JBool" / "JNumber" / "JString" /
/// "JArray" / "JObject".
// @PLN10 — return an owned `String` instead of a `Str` borrowed from the
// never-cleared `stores.scratch`.  The native binding wraps text-var assignments
// in `(...).to_string()` and argument sites in `&*` (both work on `String` via
// `Deref<Target=str>`), so this is transparent and strictly better — the owned
// String is freed instead of leaked.
pub fn t_9JsonValue_kind(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> String {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    let s = match discr {
        x if x == crate::native::JV_DISCR_NULL => "JNull",
        x if x == crate::native::JV_DISCR_BOOL => "JBool",
        x if x == crate::native::JV_DISCR_NUMBER => "JNumber",
        x if x == crate::native::JV_DISCR_STRING => "JString",
        x if x == crate::native::JV_DISCR_ARRAY => "JArray",
        x if x == crate::native::JV_DISCR_OBJECT => "JObject",
        x if x == crate::native::JV_DISCR_INT => "JInteger",
        _ => "JNull",
    };
    s.to_string()
}

// ─── Remaining JSON natives (P54 / P268 follow-up) ─────────────

/// JsonValue.as_number() — return the JNumber payload, or NaN
/// for any other variant.  Mirrors interp `n_as_number`.
pub fn t_9JsonValue_as_number(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> f64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    // @PLN109 — a JInteger widens to f64; a JNumber reads as-is.
    if discr == crate::native::JV_DISCR_NUMBER {
        let num_tp = stores.name("JNumber");
        let value_pos = u32::from(stores.position(num_tp, "value")) + v.pos;
        stores.store(&v).get_float(v.rec, value_pos)
    } else if discr == crate::native::JV_DISCR_INT {
        let int_tp = stores.name("JInteger");
        let value_pos = u32::from(stores.position(int_tp, "value")) + v.pos;
        #[allow(clippy::cast_precision_loss)]
        {
            stores.store(&v).get_int(v.rec, value_pos) as f64
        }
    } else {
        f64::NAN
    }
}

/// JsonValue.as_bool() — the JBool payload, or the tri-state NULL byte for any other
/// variant, which is what the declaration's `boolean?` promises.  Mirrors interp `n_as_bool`.
pub fn t_9JsonValue_as_bool(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> u8 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    if discr == crate::native::JV_DISCR_BOOL {
        let bool_tp = stores.name("JBool");
        let value_pos = u32::from(stores.position(bool_tp, "value")) + v.pos;
        u8::from(stores.store(&v).get_byte(v.rec, value_pos, 0) != 0)
    } else {
        // The tri-state null (C73 / @PLN17), which the `boolean?` return renders as `u8`.
        255
    }
}

/// JsonValue.has_field(name) — true iff the receiver is a JObject
/// containing a field with the given name.  Mirrors interp `n_has_field`.
#[allow(clippy::missing_panics_doc)] // try_from on a non-negative loop counter
pub fn t_9JsonValue_has_field(cell: &std::cell::UnsafeCell<Stores>, v: DbRef, name: &str) -> bool {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    if discr != crate::native::JV_DISCR_OBJECT {
        return false;
    }
    let obj_tp = stores.name("JObject");
    let fields_pos = u32::from(stores.position(obj_tp, "fields")) + v.pos;
    let fields_rec = stores.store(&v).get_i32_raw(v.rec, fields_pos);
    if fields_rec <= 0 {
        return false;
    }
    let length = i64::from(stores.store(&v).get_u32_raw(fields_rec as u32, 4));
    let jf_tp = stores.name("JsonField");
    let jf_size = u32::from(stores.size(jf_tp));
    let name_field_pos = u32::from(stores.position(jf_tp, "name"));
    for i in 0..length {
        let elm_offset = 8u32 + u32::try_from(i).expect("non-negative length") * jf_size;
        let name_rec = stores
            .store(&v)
            .get_u32_raw(fields_rec as u32, elm_offset + name_field_pos);
        let stored_name = stores.store(&v).get_str(name_rec).to_owned();
        if stored_name == name {
            return true;
        }
    }
    false
}

/// JsonValue.keys() — returns vector<text> of the JObject's field
/// names in insertion order, or empty vector for any other variant.
/// Mirrors interp `n_keys`.
#[allow(clippy::missing_panics_doc)] // try_from on a non-negative loop counter
pub fn t_9JsonValue_keys(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    let text_tp = stores.name("text");
    let text_size = u32::from(stores.size(text_tp));
    let vec = stores.database(text_size.max(1));
    stores.store_mut(&vec).set_u32_raw(vec.rec, vec.pos, 0);
    if discr != crate::native::JV_DISCR_OBJECT {
        return vec;
    }
    let obj_tp = stores.name("JObject");
    let fields_pos = u32::from(stores.position(obj_tp, "fields")) + v.pos;
    let fields_rec = stores.store(&v).get_i32_raw(v.rec, fields_pos);
    if fields_rec <= 0 {
        return vec;
    }
    let length = i64::from(stores.store(&v).get_u32_raw(fields_rec as u32, 4));
    let jf_tp = stores.name("JsonField");
    let jf_size = u32::from(stores.size(jf_tp));
    let name_field_pos = u32::from(stores.position(jf_tp, "name"));
    for i in 0..length {
        let elm_offset = 8u32 + u32::try_from(i).expect("non-negative length") * jf_size;
        let name_rec_in_jobject = stores
            .store(&v)
            .get_u32_raw(fields_rec as u32, elm_offset + name_field_pos);
        let name_str = stores.store(&v).get_str(name_rec_in_jobject).to_owned();
        let elm = crate::vector::vector_append(&vec, text_size, &mut stores.allocations);
        let new_name_rec = stores.store_mut(&elm).set_str(&name_str);
        stores
            .store_mut(&elm)
            .set_u32_raw(elm.rec, elm.pos, new_name_rec);
        crate::vector::vector_finish(&vec, &mut stores.allocations);
    }
    vec
}

/// JsonValue.fields() — returns vector<JsonField> of the JObject's
/// (name, value) entries with values deep-copied into the result
/// arena.  Empty vector for any other variant.  Mirrors interp
/// `n_fields`.
#[allow(clippy::missing_panics_doc)] // try_from on a non-negative loop counter
pub fn t_9JsonValue_fields(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let discr = stores.store(&v).get_byte(v.rec, v.pos, 0);
    let jf_tp = stores.name("JsonField");
    let jf_size = u32::from(stores.size(jf_tp));
    let vec = stores.database(jf_size.max(1));
    stores.store_mut(&vec).set_u32_raw(vec.rec, vec.pos, 0);
    if discr != crate::native::JV_DISCR_OBJECT {
        return vec;
    }
    let obj_tp = stores.name("JObject");
    let fields_pos = u32::from(stores.position(obj_tp, "fields")) + v.pos;
    let fields_rec = stores.store(&v).get_i32_raw(v.rec, fields_pos);
    if fields_rec <= 0 {
        return vec;
    }
    let length = i64::from(stores.store(&v).get_u32_raw(fields_rec as u32, 4));
    let name_field_pos = u32::from(stores.position(jf_tp, "name"));
    let value_field_pos = u32::from(stores.position(jf_tp, "value"));
    // Two-pass: read the source under `&Stores`, write under `&mut Stores`.
    let mut entries: Vec<(String, crate::json::Parsed)> = Vec::with_capacity(length as usize);
    for i in 0..length {
        let elm_offset = 8u32 + u32::try_from(i).expect("non-negative length") * jf_size;
        let name_rec = stores
            .store(&v)
            .get_u32_raw(fields_rec as u32, elm_offset + name_field_pos);
        let name = stores.store(&v).get_str(name_rec).to_owned();
        let value_slot = DbRef {
            store_nr: v.store_nr,
            rec: fields_rec as u32,
            pos: elm_offset + value_field_pos,
        };
        entries.push((name, crate::native::dbref_to_parsed(stores, &value_slot)));
    }
    for (name, value) in entries {
        let elm = crate::vector::vector_append(&vec, jf_size, &mut stores.allocations);
        let new_name_rec = stores.store_mut(&elm).set_str(&name);
        stores
            .store_mut(&elm)
            .set_u32_raw(elm.rec, elm.pos + name_field_pos, new_name_rec);
        let value_slot = DbRef {
            store_nr: elm.store_nr,
            rec: elm.rec,
            pos: elm.pos + value_field_pos,
        };
        crate::native::materialise_primitive_into(stores, &value_slot, &value);
        crate::vector::vector_finish(&vec, &mut stores.allocations);
    }
    vec
}

/// JsonValue.to_json() — canonical RFC 8259 serialiser.  Delegates
/// to the shared `crate::native::json_to_text` (used by interp + native).
// @PLN10 — owned `String` instead of a scratch-`Str` (same path as `kind`:
// the native binding bridges via `.to_string()` / `&*`).
pub fn t_9JsonValue_to_json(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> String {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    crate::native::json_to_text(stores, &v, false)
}

/// JsonValue.to_json_pretty() — 2-space-indent serialiser.  Same
/// shared helper as `to_json`, with the `pretty` flag set.
// @PLN10 — owned `String` instead of a scratch-`Str` (same path as `kind`).
pub fn t_9JsonValue_to_json_pretty(cell: &std::cell::UnsafeCell<Stores>, v: DbRef) -> String {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    crate::native::json_to_text(stores, &v, true)
}

/// json_null() — allocate a JsonValue set to the JNull variant.
pub fn n_json_null(cell: &std::cell::UnsafeCell<Stores>) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let result = crate::native::jv_alloc(stores);
    stores
        .store_mut(&result)
        .set_byte(result.rec, result.pos, 0, crate::native::JV_DISCR_NULL);
    stores.last_json_errors.clear();
    result
}

/// json_bool(v) — allocate a JsonValue set to the JBool variant.
pub fn n_json_bool(cell: &std::cell::UnsafeCell<Stores>, v: u8) -> DbRef {
    // @PLN17: boolean storage form is u8; canonicalise to 0/1 for the JBool byte.
    let v = v == 1;
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let result = crate::native::jv_alloc(stores);
    let pos = result.pos;
    let bool_tp = stores.name("JBool");
    let value_pos = u32::from(stores.position(bool_tp, "value")) + pos;
    let store_mut = stores.store_mut(&result);
    store_mut.set_byte(result.rec, pos, 0, crate::native::JV_DISCR_BOOL);
    store_mut.set_byte(result.rec, value_pos, 0, i32::from(v));
    stores.last_json_errors.clear();
    result
}

/// json_number(n) — allocate a JsonValue set to the JNumber variant.
/// Non-finite inputs produce JNull + diagnostic in `json_errors()`.
pub fn n_json_number(cell: &std::cell::UnsafeCell<Stores>, n: f64) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let result = crate::native::jv_alloc(stores);
    let pos = result.pos;
    if n.is_finite() {
        let num_tp = stores.name("JNumber");
        let value_pos = u32::from(stores.position(num_tp, "value")) + pos;
        let store_mut = stores.store_mut(&result);
        store_mut.set_byte(result.rec, pos, 0, crate::native::JV_DISCR_NUMBER);
        store_mut.set_float(result.rec, value_pos, n);
        stores.last_json_errors.clear();
    } else {
        stores
            .store_mut(&result)
            .set_byte(result.rec, pos, 0, crate::native::JV_DISCR_NULL);
        stores.last_json_errors.clear();
        stores
            .last_json_errors
            .push(format!("json_number: non-finite value {n} stored as JNull"));
    }
    result
}

/// json_string(s) — allocate a JsonValue set to the JString variant
/// holding a copy of the input text.
pub fn n_json_string(cell: &std::cell::UnsafeCell<Stores>, s: &str) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let s_owned = s.to_owned();
    let result = crate::native::jv_alloc(stores);
    let pos = result.pos;
    let str_tp = stores.name("JString");
    let value_pos = u32::from(stores.position(str_tp, "value")) + pos;
    let s_rec = stores.store_mut(&result).set_str(&s_owned);
    let store_mut = stores.store_mut(&result);
    store_mut.set_byte(result.rec, pos, 0, crate::native::JV_DISCR_STRING);
    store_mut.set_u32_raw(result.rec, value_pos, s_rec);
    stores.last_json_errors.clear();
    result
}

/// json_array(items) — allocate a JArray JsonValue carrying a deep
/// copy of `items`'s elements.  Mirrors interp `n_json_array`.
pub fn n_json_array(cell: &std::cell::UnsafeCell<Stores>, items: DbRef) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let length = crate::vector::length_vector(&items, &stores.allocations);
    let result = crate::native::jv_alloc(stores);
    if length == 0 {
        stores.store_mut(&result).set_byte(
            result.rec,
            result.pos,
            0,
            crate::native::JV_DISCR_ARRAY,
        );
        stores.last_json_errors.clear();
        return result;
    }
    let input_inner_rec = stores.store(&items).get_u32_raw(items.rec, items.pos);
    let jv_tp = stores.name("JsonValue");
    let jv_size = u32::from(stores.size(jv_tp));
    let mut children = Vec::with_capacity(length as usize);
    for i in 0..length {
        let elem_offset = 8u32 + i * jv_size;
        let src_elm = DbRef {
            store_nr: items.store_nr,
            rec: input_inner_rec,
            pos: elem_offset,
        };
        children.push(crate::native::dbref_to_parsed(stores, &src_elm));
    }
    crate::native::materialise_primitive_into(
        stores,
        &result,
        &crate::json::Parsed::Array(children),
    );
    stores.last_json_errors.clear();
    result
}

/// json_object(fields) — allocate a JObject JsonValue carrying a
/// deep copy of `fields`'s (name, value) entries.  Mirrors interp
/// `n_json_object`.
pub fn n_json_object(cell: &std::cell::UnsafeCell<Stores>, fields: DbRef) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let length = crate::vector::length_vector(&fields, &stores.allocations);
    let result = crate::native::jv_alloc(stores);
    if length == 0 {
        stores.store_mut(&result).set_byte(
            result.rec,
            result.pos,
            0,
            crate::native::JV_DISCR_OBJECT,
        );
        stores.last_json_errors.clear();
        return result;
    }
    let input_inner_rec = stores.store(&fields).get_u32_raw(fields.rec, fields.pos);
    let jf_tp = stores.name("JsonField");
    let jf_size = u32::from(stores.size(jf_tp));
    let name_field_pos = u32::from(stores.position(jf_tp, "name"));
    let value_field_pos = u32::from(stores.position(jf_tp, "value"));
    let mut entries: Vec<(String, usize, crate::json::Parsed)> =
        Vec::with_capacity(length as usize);
    for i in 0..length {
        let elem_offset = 8u32 + i * jf_size;
        let name_rec = stores
            .store(&fields)
            .get_u32_raw(input_inner_rec, elem_offset + name_field_pos);
        let name = stores.store(&fields).get_str(name_rec).to_owned();
        let value_slot = DbRef {
            store_nr: fields.store_nr,
            rec: input_inner_rec,
            pos: elem_offset + value_field_pos,
        };
        entries.push((
            name,
            0usize,
            crate::native::dbref_to_parsed(stores, &value_slot),
        ));
    }
    crate::native::materialise_primitive_into(
        stores,
        &result,
        &crate::json::Parsed::Object(entries),
    );
    stores.last_json_errors.clear();
    result
}

/// struct_from_jsonvalue(v, struct_kt) — build a struct of type
/// `struct_kt` populated from JsonValue `v`.  Mirrors interp
/// `n_struct_from_jsonvalue`.
pub fn n_struct_from_jsonvalue(
    cell: &std::cell::UnsafeCell<Stores>,
    v: DbRef,
    struct_kt: i64,
) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let struct_kt = (struct_kt as i32) as u16;
    let bytes = u32::from(stores.size(struct_kt));
    let words = bytes.div_ceil(8) + 1;
    let result = stores.database(words.max(2));
    crate::native::populate_struct_from_jsonvalue(stores, &result, struct_kt, &v);
    result
}

/// struct_to_json(self_ref, struct_kt) — serialise any user struct
/// to canonical JSON.  Mirrors interp `n_struct_to_json`.
// @PLN10 — owned `String` instead of a scratch-`Str` (cell-ABI path, bridged
// by the native binding's `.to_string()` / `&*`).
pub fn n_struct_to_json(
    cell: &std::cell::UnsafeCell<Stores>,
    self_ref: DbRef,
    struct_kt: i64,
) -> String {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let struct_kt = (struct_kt as i32) as u16;
    let mut out = String::new();
    stores.show_json(&mut out, &self_ref, struct_kt, false);
    out
}

/// struct_to_json_pretty(self_ref, struct_kt) — pretty serialiser.
/// Mirrors interp `n_struct_to_json_pretty`.
// @PLN10 — owned `String` instead of a scratch-`Str`.
pub fn n_struct_to_json_pretty(
    cell: &std::cell::UnsafeCell<Stores>,
    self_ref: DbRef,
    struct_kt: i64,
) -> String {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let struct_kt = (struct_kt as i32) as u16;
    let mut out = String::new();
    stores.show_json(&mut out, &self_ref, struct_kt, true);
    out
}

/// Read the lock state of the store that owns the record pointed to by `r`.
/// Bytecode equivalent: `n_get_store_lock` in `src/native.rs`.
pub fn n_get_store_lock(cell: &std::cell::UnsafeCell<Stores>, r: DbRef) -> bool {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores.is_store_locked(&r)
}

/// Lock or unlock the store that owns the record pointed to by `r`.
/// Bytecode equivalent: `n_set_store_lock` in `src/native.rs`.
pub fn n_set_store_lock(cell: &std::cell::UnsafeCell<Stores>, r: DbRef, locked: u8) {
    // @PLN17: boolean storage form is u8 (0/1/255); locked iff the true byte (1).
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if locked == 1 {
        stores.lock_store(&r);
    } else {
        stores.unlock_store(&r);
    }
}

/// @P290 — soft free-protect marker for the fn-call deep-copy bracket.
/// Counterpart of `n_protect_store_frees` in `src/native.rs`.
pub fn n_protect_store_frees(cell: &std::cell::UnsafeCell<Stores>, r: DbRef) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if r.rec != 0 && (r.store_nr as usize) < stores.allocations.len() {
        let origin = format!("call_bracket(store_nr={}, rec={})", r.store_nr, r.rec);
        stores.allocations[r.store_nr as usize].set_free_protected(origin);
    }
}

/// @P290 — clear the soft free-protection.
pub fn n_unprotect_store_frees(cell: &std::cell::UnsafeCell<Stores>, r: DbRef) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    if r.rec != 0 && (r.store_nr as usize) < stores.allocations.len() {
        stores.allocations[r.store_nr as usize].clear_free_protected();
    }
}

// @PLAN12 phase 3.5a (2026-05-24) — n_rand / n_rand_seed /
// n_rand_indices removed.  All three live in lib/random/native/'s
// cdylib now; native codegen reaches them via `extern crate
// loft_random;` + `crate::n_*(...)` qualified calls, with LoftStore
// forwarded by `loft::native_call::build_store` for the
// store-allocating n_rand_indices.

/// Allocate a result vector of `n` elements, each `elem_size` bytes, and run
/// `worker(stores, element_dbref)` on every element, storing the result.
/// For native code, the caller passes a closure that calls the right Rust function.
/// Returns a `DbRef` to the result store; the caller frees it with `OpFreeRef`.
/// Memory layout matches bytecode `n_parallel_for`:
///   `header_rec`, `pos=4` → `i32` pointing to `vec_rec`
///   `vec_rec`, `pos=4`    → element count (`n`)
///   `vec_rec`, `pos=8+i*S` → element `i`  (`S` = 4 int / 8 long+float / 1 bool bytes)
///
/// Runs workers in parallel via the shared `parallel::parallel_workers`
/// template (rayon work-stealing pool, plan-06 phase 1.5), mirroring the
/// interp path's `run_parallel_direct` in `src/parallel.rs` (post-phase-3c).
/// Plan-06 phase 3b.1 — shared prologue for the native par result store.
///
/// Allocates a result store (`stores.null()`), reserves the vector body
/// (`n * elem_size` bytes) plus its 1-word header record, and returns the
/// triple (result_db, vec_rec, header_rec) the three native par variants
/// all need.  Replaces ~7 lines of identical boilerplate at the top of
/// each `n_parallel_for_*_native`.
fn alloc_par_result(stores: &mut Stores, n: usize, elem_size: u32) -> (DbRef, u32, u32) {
    let result_db = stores.null();
    let vec_words = ((n as u32) * elem_size + 15) / 8;
    let vec_cr = stores.claim(&result_db, vec_words.max(1));
    let header_cr = stores.claim(&result_db, 1);
    (result_db, vec_cr.rec, header_cr.rec)
}

/// Plan-06 phase 3b.1 — shared epilogue for the native par result store.
///
/// Writes the vector length into `vec_rec[4]`, points the header record's
/// pos=4 slot at `vec_rec`, and returns the canonical `DbRef { …, pos: 4 }`
/// every par caller expects.  Replaces ~10 lines of identical boilerplate
/// at the bottom of each `n_parallel_for_*_native`.
fn finalize_par_result(
    stores: &mut Stores,
    result_db: DbRef,
    n: usize,
    vec_rec: u32,
    header_rec: u32,
) -> DbRef {
    let store = stores.store_mut(&result_db);
    store.set_u32_raw(vec_rec, 4, n as u32);
    store.set_u32_raw(header_rec, 4, vec_rec);
    DbRef {
        store_nr: result_db.store_nr,
        rec: header_rec,
        pos: 4,
    }
}

/// Plan-09 phase 09: shape-trait-driven parallel-for runtime.
///
/// The three native par variants (scalar / text / heap-ref) share an
/// allocate-→-dispatch-workers-→-merge-→-finalise skeleton.  This
/// trait factors the per-shape pieces — return-element width, worker
/// dispatcher, merge logic — out of the public fns so each public fn
/// reduces to a thin wrapper around the generic core.
///
/// The trait spans more variation than a single closure return type:
/// `TextShape` runs workers via per-worker store slots that intern
/// strings via `set_str`; `RefShape` carries each worker's `Stores`
/// back so the parent can deep-copy structs across the worker/parent
/// boundary.  `Self::Batches` therefore varies per shape, and the
/// merge-into-result-store step lives on the trait too.
trait ParShape {
    /// Closure return type passed back from each worker invocation.
    type WorkerOut: Send;
    /// Shape-specific value carried from the worker phase into the
    /// merge phase (`Vec<i64>` for scalar, `Vec<String>` for text,
    /// `Vec<(Vec<(usize, DbRef)>, Stores)>` for ref).
    type Batches;

    /// Element width in the result vector (the third arg to
    /// `alloc_par_result`).  4 for text, struct-size for ref,
    /// `return_size.clamp(1, 8)` for scalar.
    fn return_sz(&self) -> u32;

    /// Run workers in parallel and gather their outputs.  Wraps the
    /// shape's existing `run_native_workers_*` helper.
    fn run_workers<F>(
        stores: &Stores,
        input: &DbRef,
        elem_size: i32,
        threads: i32,
        n: usize,
        worker: &F,
    ) -> Self::Batches
    where
        F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> Self::WorkerOut + Send + Sync,
        Self: Sized;

    /// Write `batches` into the result vector at `vec_rec`,
    /// starting at byte offset 8.  Per-shape: scalar writes
    /// long/i32/byte; text interns + writes a 4-byte s_pos; ref
    /// deep-copies via `copy_from_worker[_unowned]`.
    fn store_results(
        &self,
        stores: &mut Stores,
        result_db: &DbRef,
        vec_rec: u32,
        batches: Self::Batches,
    );
}

struct ScalarShape {
    return_size: i32,
}

impl ParShape for ScalarShape {
    type WorkerOut = i64;
    type Batches = Vec<i64>;

    fn return_sz(&self) -> u32 {
        self.return_size.clamp(1, 8) as u32
    }

    fn run_workers<F>(
        stores: &Stores,
        input: &DbRef,
        elem_size: i32,
        threads: i32,
        n: usize,
        worker: &F,
    ) -> Self::Batches
    where
        F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> i64 + Send + Sync,
    {
        run_native_workers_primitive(stores, input, elem_size, threads, n, worker)
    }

    fn store_results(
        &self,
        stores: &mut Stores,
        result_db: &DbRef,
        vec_rec: u32,
        batches: Vec<i64>,
    ) {
        let return_sz = self.return_sz();
        let mut fld = 8u32;
        for &val in &batches {
            let store = stores.store_mut(result_db);
            match return_sz {
                8 => {
                    store.set_long(vec_rec, fld, val);
                }
                1 => {
                    store.set_byte(vec_rec, fld, 0, val as i32);
                }
                _ => {
                    store.set_i32_raw(vec_rec, fld, val as i32);
                }
            }
            fld += return_sz;
        }
    }
}

struct TextShape;

impl ParShape for TextShape {
    type WorkerOut = String;
    type Batches = Vec<String>;

    fn return_sz(&self) -> u32 {
        4
    }

    fn run_workers<F>(
        stores: &Stores,
        input: &DbRef,
        elem_size: i32,
        threads: i32,
        n: usize,
        worker: &F,
    ) -> Self::Batches
    where
        F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> String + Send + Sync,
    {
        run_native_workers_text(stores, input, elem_size, threads, n, worker)
    }

    fn store_results(
        &self,
        stores: &mut Stores,
        result_db: &DbRef,
        vec_rec: u32,
        batches: Vec<String>,
    ) {
        for (i, s) in batches.iter().enumerate() {
            let store = stores.store_mut(result_db);
            let s_pos = store.set_str(s);
            store.set_u32_raw(vec_rec, 8 + (i as u32) * 4, s_pos);
        }
    }
}

struct RefShape {
    struct_size: i32,
    known_type: i32,
}

impl ParShape for RefShape {
    type WorkerOut = DbRef;
    type Batches = Vec<(Vec<(usize, DbRef)>, Stores)>;

    fn return_sz(&self) -> u32 {
        self.struct_size as u32
    }

    fn run_workers<F>(
        stores: &Stores,
        input: &DbRef,
        elem_size: i32,
        threads: i32,
        n: usize,
        worker: &F,
    ) -> Self::Batches
    where
        F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> DbRef + Send + Sync,
    {
        run_native_workers_ref(stores, input, elem_size, threads, n, worker)
    }

    fn store_results(
        &self,
        stores: &mut Stores,
        result_db: &DbRef,
        vec_rec: u32,
        batches: Self::Batches,
    ) {
        let sz = self.return_sz();
        let kt = self.known_type as u16;
        // Phase 2 step 2b: cheap path for self-contained structs.
        let unowned = !stores.has_owned_sub_fields(kt);
        for (batch, mut worker_stores) in batches {
            for (i, src_ref) in batch {
                let dest = DbRef {
                    store_nr: result_db.store_nr,
                    rec: vec_rec,
                    pos: 8 + (i as u32) * sz,
                };
                if unowned {
                    stores.copy_from_worker_unowned(&src_ref, &dest, &mut worker_stores, kt);
                } else {
                    stores.copy_from_worker(&src_ref, &dest, &mut worker_stores, kt);
                }
            }
        }
    }
}

/// Generic parallel-for core — consumed by the three public
/// `n_parallel_for_*_native` wrappers below.  Replaces the
/// allocate-→-dispatch-→-merge-→-finalise body each variant used
/// to inline.
fn n_parallel_for_native_core<S, F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    elem_size: i32,
    threads: i32,
    shape: &S,
    worker: F,
) -> DbRef
where
    S: ParShape,
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> S::WorkerOut + Send + Sync,
{
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let n = vector::length_vector(&input, &stores.allocations) as usize;
    let return_sz = shape.return_sz();
    let (result_db, vec_rec, header_rec) = alloc_par_result(stores, n, return_sz);
    let batches = S::run_workers(stores, &input, elem_size, threads, n, &worker);
    shape.store_results(stores, &result_db, vec_rec, batches);
    finalize_par_result(stores, result_db, n, vec_rec, header_rec)
}

pub fn n_parallel_for_native<F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    elem_size: i32,
    return_size: i32,
    threads: i32,
    worker: F,
) -> DbRef
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> i64 + Send + Sync,
{
    n_parallel_for_native_core(
        cell,
        input,
        elem_size,
        threads,
        &ScalarShape { return_size },
        worker,
    )
}

/// Parallel worker dispatcher for native primitive-return par.
/// Mirrors `src/parallel.rs::run_parallel_raw` but takes a Rust closure
/// instead of a bytecode fn pos.  Each thread borrows the parent stores
/// read-only via `parallel_workers` (`clone_for_light_worker`); per-thread
/// results merge on the main thread.
fn run_native_workers_primitive<F>(
    stores: &Stores,
    input: &DbRef,
    elem_size: i32,
    n_threads: i32,
    n: usize,
    worker: &F,
) -> Vec<i64>
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> i64 + Send + Sync,
{
    if n == 0 {
        return Vec::new();
    }
    let input_t = *input;
    let n_threads = n_threads.max(1) as usize;
    let batches = crate::parallel::parallel_workers(stores, n_threads, n, |start, end, mut ws| {
        let mut local: Vec<i64> = Vec::with_capacity(end - start);
        for row_idx in start..end {
            let elm =
                vector::get_vector(&input_t, elem_size as u32, row_idx as i64, &ws.allocations);
            // P199 — generated worker closures take `&UnsafeCell<Stores>`
            // (the new ABI).  Cast `&mut ws.stores` to `&UnsafeCell<Stores>`
            // via the `repr(transparent)` layout guarantee.
            let cell: &std::cell::UnsafeCell<Stores> =
                unsafe { &*(&raw mut ws.stores as *const std::cell::UnsafeCell<Stores>) };
            local.push(worker(cell, elm));
        }
        (start, local)
    });
    crate::parallel::merge_batches(batches, n, 0i64)
}

/// Text-returning variant of `n_parallel_for_native`.  The worker closure returns
/// an owned `String`; each result is stored in the result store via `set_str` and
/// the 4-byte text position is written into the result vector.
///
/// Same parallelization shape as `n_parallel_for_native` — uses the
/// shared `parallel::parallel_workers` template.  Each worker
/// accumulates `Vec<String>`; main-thread re-sequences and writes
/// strings into the result store via `set_str` after join.
pub fn n_parallel_for_text_native<F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    elem_size: i32,
    _return_size: i32,
    threads: i32,
    worker: F,
) -> DbRef
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> String + Send + Sync,
{
    n_parallel_for_native_core(cell, input, elem_size, threads, &TextShape, worker)
}

/// Parallel worker dispatcher for native text-return par.
///
/// Plan-06 phase 1b: each worker reserves a per-worker output Store
/// slot holding a `row_count`-entry s_pos array; the slot's store
/// also interns the worker's text-bytes via `set_str`.  After join,
/// the parent reads each adopted slot's s_pos array, retrieves the
/// strings via `get_str`, and copies them into the caller's
/// `Vec<String>`.  Replaces the prior per-thread `Vec<String>` heap
/// accumulator — text results now flow through the same store-typed
/// pipeline as every other field write.
fn run_native_workers_text<F>(
    stores: &Stores,
    input: &DbRef,
    elem_size: i32,
    n_threads: i32,
    n: usize,
    worker: &F,
) -> Vec<String>
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> String + Send + Sync,
{
    if n == 0 {
        return Vec::new();
    }
    let input_t = *input;
    let n_threads = n_threads.max(1) as usize;
    let batches = crate::parallel::parallel_workers(stores, n_threads, n, |start, end, mut ws| {
        let row_count = end - start;
        let array_words = (row_count * 4).div_ceil(8).max(1) as u32;
        let slot = ws.add_output_slot(array_words);
        let array_rec = ws.stores.allocations[slot.store_nr as usize].claim(array_words);
        for (local_idx, row_idx) in (start..end).enumerate() {
            let elm = vector::get_vector(
                &input_t,
                elem_size as u32,
                row_idx as i64,
                &ws.stores.allocations,
            );
            // P199 — see run_native_workers_primitive comment.
            let cell: &std::cell::UnsafeCell<Stores> =
                unsafe { &*(&raw mut ws.stores as *const std::cell::UnsafeCell<Stores>) };
            let s = worker(cell, elm);
            let slot_store = &mut ws.stores.allocations[slot.store_nr as usize];
            let s_pos = slot_store.set_str(&s);
            slot_store.set_u32_raw(array_rec, (local_idx as u32) * 4, s_pos);
        }
        (start, row_count, slot.store_nr, array_rec, ws.stores)
    });
    let mut results = vec![String::new(); n];
    for (start, count, slot_nr, array_rec, worker_stores) in batches {
        let slot_store = &worker_stores.allocations[slot_nr as usize];
        for local_idx in 0..count {
            let s_pos = slot_store.get_u32_raw(array_rec, (local_idx as u32) * 4);
            results[start + local_idx] = slot_store.get_str(s_pos).to_string();
        }
    }
    results
}

/// Reference/struct-returning variant of `n_parallel_for_native`.  The worker closure
/// returns a `DbRef` pointing to a newly created struct.  Each result is deep-copied
/// (raw bytes + owned sub-fields) inline into the result vector so that `OpGetVector`
/// returns a `DbRef` that supports field access without extra indirection.
///
/// `struct_size` is the inline byte size of the struct (from `stores.size(known_type)`).
/// `known_type` is the struct's type id for `copy_block` / `copy_claims`.
///
/// Workers run in parallel via the shared `parallel::parallel_workers`
/// template (rayon work-stealing pool); each worker returns its
/// `Vec<(idx, src_ref)>` batch plus its `WorkerStores`, and the main
/// thread deep-copies each struct into the result vector via
/// `copy_from_worker`'s graft machinery (or `copy_from_worker_unowned`
/// for owned-free struct/variant payloads — plan-06 phase 2b refinement).
/// Mirrors how `src/native.rs` wires `run_parallel_ref` for the
/// interpreter path.
pub fn n_parallel_for_ref_native<F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    elem_size: i32,
    struct_size: i32,
    known_type: i32,
    threads: i32,
    worker: F,
) -> DbRef
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> DbRef + Send + Sync,
{
    n_parallel_for_native_core(
        cell,
        input,
        elem_size,
        threads,
        &RefShape {
            struct_size,
            known_type,
        },
        worker,
    )
}

/// Parallel worker dispatcher for native struct/reference-return par.
/// Each thread accumulates `(row_idx, struct_ref_in_worker_store)` pairs
/// and returns its batch plus its full `Stores` clone.  The caller uses
/// `Stores::copy_from_worker` to deep-copy each struct into the result
/// vector across the worker / parent store boundary.
fn run_native_workers_ref<F>(
    stores: &Stores,
    input: &DbRef,
    elem_size: i32,
    n_threads: i32,
    n: usize,
    worker: &F,
) -> Vec<(Vec<(usize, DbRef)>, Stores)>
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> DbRef + Send + Sync,
{
    if n == 0 {
        return Vec::new();
    }
    let input_t = *input;
    let n_threads = n_threads.max(1) as usize;
    crate::parallel::parallel_workers(stores, n_threads, n, |start, end, mut ws| {
        let mut batch: Vec<(usize, DbRef)> = Vec::with_capacity(end - start);
        for row_idx in start..end {
            let elm =
                vector::get_vector(&input_t, elem_size as u32, row_idx as i64, &ws.allocations);
            // P199 — see run_native_workers_primitive comment.
            let cell: &std::cell::UnsafeCell<Stores> =
                unsafe { &*(&raw mut ws.stores as *const std::cell::UnsafeCell<Stores>) };
            let r = worker(cell, elm);
            batch.push((row_idx, r));
        }
        (batch, ws.stores)
    })
}

// ── Plan-09 phase 06: parallel-queue runtime (P202 close) ──────────────────
//
// Mirror of the interpreter's `n_parallel_queue*` family in
// `src/native.rs`, adapted to the native ABI: takes a Rust closure
// instead of a bytecode worker fn.  Workers run via the same
// `run_native_workers_*` helpers used by `n_parallel_for_*_native`;
// the difference is in the merge phase — instead of writing into a
// result vector, results are pushed onto `stores.par_*_buffer_stack`
// and the row count is returned for use as a loop bound.
//
// The accompanying `n_parallel_buf_get_*_native` / `_drop_*_native`
// fns provide the per-row read + cleanup that loft's fused for-par
// desugars into.

/// `parallel { arm; arm }` runtime entry — the native half of
/// [`crate::parallel::run_parallel_block`].
///
/// Each arm runs concurrently against its OWN read-only clone of the parent's stores,
/// which is what lets an arm read enclosing state and write nothing back.  The parser
/// enforces that half at compile time: writing an enclosing local, mutating one through a
/// reference, or capturing a parameter is a compile error, not a silent no-op
/// (`170-parallel-capture-soundness.loft`).  So an arm closure captures only shared
/// references, and the `Fn + Send + Sync` bound below is a bound the language already
/// guarantees rather than one the generator has to arrange.
///
/// One arm per worker, deliberately: an arm is a named unit of the program the author
/// wrote, not a row of a collection, so there is no batching decision to make.
///
/// The block form had no native lowering at all until loft#1054 — it was emitted as a
/// COMMENT, so the arms never ran and the program exited 0 having done none of the work.
pub fn n_parallel_block_native(
    cell: &std::cell::UnsafeCell<Stores>,
    arms: &[&(dyn Fn(&std::cell::UnsafeCell<Stores>) + Send + Sync)],
) {
    if arms.is_empty() {
        return;
    }
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let _: Vec<()> =
        crate::parallel::parallel_workers(stores, arms.len(), arms.len(), |start, end, mut ws| {
            for arm in &arms[start..end] {
                // P199 — see `run_native_workers_primitive` for the `&UnsafeCell<Stores>`
                // cast; generated arm closures take the same ABI a worker closure does.
                let cell: &std::cell::UnsafeCell<Stores> =
                    unsafe { &*(&raw mut ws.stores as *const std::cell::UnsafeCell<Stores>) };
                arm(cell);
            }
        });
}

/// Plan-06 spine step 3 (native variant) — `Stitch::Discard` runtime entry.
///
/// Runs the worker over every input row and keeps nothing: no result vector, no
/// buffer, no merge.  That is the whole point of the route — the parser picks it
/// for `for x in v par(r = f(x), N) { }`, where the body never names the result.
///
/// It exists because the declaration-driven fallback cannot express it.  Every other
/// par route has a bespoke lowering that builds the worker closure; the discard route
/// had none, so `--native` emitted `n_parallel_discard`'s loft DECLARATION with an
/// empty body — workers that would never run.  What made that visible rather than
/// silent was an unrelated arity mismatch in the same emit, which is not a thing to
/// rely on (loft#987).
///
/// The closure returns `()` rather than the worker's own value: with the result
/// dropped, the return shape stops mattering, so one runner covers every worker —
/// scalar, float, text and heap-reference alike.
pub fn n_parallel_discard_native<F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    elem_size: i32,
    threads: i32,
    worker: F,
) where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) + Send + Sync,
{
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let n = vector::length_vector(&input, &stores.allocations) as usize;
    if n == 0 {
        return;
    }
    let input_t = input;
    let n_threads = (threads.max(1) as usize).min(n);
    let _: Vec<()> =
        crate::parallel::parallel_workers(stores, n_threads, n, |start, end, mut ws| {
            for row_idx in start..end {
                let elm =
                    vector::get_vector(&input_t, elem_size as u32, row_idx as i64, &ws.allocations);
                // P199 — see `run_native_workers_primitive` for the `&UnsafeCell<Stores>`
                // cast; generated worker closures take the new ABI.
                let cell: &std::cell::UnsafeCell<Stores> =
                    unsafe { &*(&raw mut ws.stores as *const std::cell::UnsafeCell<Stores>) };
                worker(cell, elm);
            }
        });
}

/// Plan-06 spine step 8a (native variant) — scalar-return Queue
/// runtime entry.  Runs workers, packs their `i64` returns into a
/// `Vec<u64>`, pushes onto `par_buffer_stack`, and returns the row
/// count.  Each worker's i64 return is bit-cast to u64 (matching
/// the interpreter's storage convention).
pub fn n_parallel_queue_native<F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    elem_size: i32,
    _return_size: i32,
    threads: i32,
    worker: F,
) -> i64
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> i64 + Send + Sync,
{
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let n = vector::length_vector(&input, &stores.allocations) as usize;
    let results = run_native_workers_primitive(stores, &input, elem_size, threads, n, &worker);
    let buf: Vec<u64> = results.into_iter().map(|v| v as u64).collect();
    stores.par_buffer_stack.push(buf);
    n as i64
}

/// Plan-06 ARC.md A5b — native runtime entry for `par_fold(items, init,
/// fn fold, threads)`.  Closure-based bridge mirroring `n_parallel_queue_native`
/// but accumulates per-thread instead of buffering one result per row.
///
/// V1: `items` is `vector<integer>` (8-byte rows), `init` and the
/// worker's accumulator/row/return are all `i64`.  Worker closure
/// signature is `Fn(&UnsafeCell<Stores>, acc, row) -> i64` — takes
/// two primitive i64 args, distinct from the queue family's
/// `Fn(cell, DbRef) -> i64` shape because fold's worker takes the row
/// as a primitive value, not a reference.
///
/// Algorithm mirrors `parallel::run_parallel_fold` (interp side):
///   1. Workers each accumulate over their slice via `worker(cell, acc, row_val)`.
///   2. Main thread combines per-thread partials in worker-completion
///      order using the same worker closure.
///
/// Shape decisions:
/// - `threads.max(1)` matches the interp side; zero/negative collapse to 1.
/// - Empty input short-circuits to `init` (no thread spawn).
/// - Per-row read is a 1-line unaligned i64 load — V1 hardcodes
///   8-byte stride.  Wider shapes (V2 heterogeneous types) belong in a
///   future ARC step.
pub fn n_parallel_fold_native<F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    init: i64,
    threads: i32,
    worker: F,
) -> i64
where
    F: Fn(&std::cell::UnsafeCell<Stores>, i64, i64) -> i64 + Send + Sync,
{
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let n = vector::length_vector(&input, &stores.allocations) as usize;
    if n == 0 {
        return init;
    }
    let partials = run_native_workers_fold(stores, &input, threads, n, init, &worker);
    // Main-thread combine in worker-completion order.  Mirror of the
    // interp-side combine in `parallel::run_parallel_fold`: feeds each
    // partial into the same worker fn with the running acc.
    let mut acc = init;
    for partial in partials {
        acc = worker(cell, acc, partial);
    }
    acc
}

/// Per-thread fold accumulator helper for `n_parallel_fold_native`.
///
/// Each worker reads V1's 8-byte i64 rows from `input`, threads them
/// through `worker(cell, acc, row_val)` from `init`, and returns the
/// final partial.  The wrapping `n_parallel_fold_native` combines the
/// partials on the main thread.
///
/// Reuses `parallel::parallel_workers` for the rayon-pool + per-thread
/// `Stores` clone plumbing (same template as `run_native_workers_primitive`).
/// Differs only in the per-thread body — accumulate-into-i64 vs
/// collect-into-Vec.
fn run_native_workers_fold<F>(
    stores: &Stores,
    input: &DbRef,
    n_threads: i32,
    n: usize,
    init: i64,
    worker: &F,
) -> Vec<i64>
where
    F: Fn(&std::cell::UnsafeCell<Stores>, i64, i64) -> i64 + Send + Sync,
{
    if n == 0 {
        return Vec::new();
    }
    let input_t = *input;
    let n_threads = n_threads.max(1) as usize;
    let mut batches =
        crate::parallel::parallel_workers(stores, n_threads, n, |start, end, mut ws| {
            let mut acc = init;
            // V1: vector<integer> rows are i64s at row position; stride is
            // 8 bytes.  Read unaligned to match `read_primitive_at` in
            // src/parallel.rs (rows can land on any 4-byte boundary).
            for row_idx in start..end {
                let elm = vector::get_vector(&input_t, 8, row_idx as i64, &ws.allocations);
                let row_val = unsafe {
                    let store = &ws.allocations[elm.store_nr as usize];
                    let base = store.base_ptr();
                    let p = base.offset(elm.rec as isize * 8 + elm.pos as isize);
                    p.cast::<i64>().read_unaligned()
                };
                // P199 — generated worker closures take `&UnsafeCell<Stores>`
                // (the new ABI).  Cast `&mut ws.stores` to `&UnsafeCell<Stores>`
                // via the `repr(transparent)` layout guarantee.
                let cell: &std::cell::UnsafeCell<Stores> =
                    unsafe { &*(&raw mut ws.stores as *const std::cell::UnsafeCell<Stores>) };
                acc = worker(cell, acc, row_val);
            }
            (start, acc)
        });
    // Sort by start index for deterministic combine order (matches
    // interp-side `run_parallel_fold` behaviour).
    batches.sort_by_key(|(start, _)| *start);
    batches.into_iter().map(|(_, acc)| acc).collect()
}

/// Plan-06 spine step 8c (native variant) — text-return Queue.
/// Workers' `String` returns are pushed verbatim onto
/// `par_text_buffer_stack`.  `n_parallel_buf_get_text_native` reads
/// them back through `stores.scratch` (lifetime-stabilising the
/// `&str` returned to the caller).
pub fn n_parallel_queue_text_native<F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    elem_size: i32,
    _return_size: i32,
    threads: i32,
    worker: F,
) -> i64
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> String + Send + Sync,
{
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let n = vector::length_vector(&input, &stores.allocations) as usize;
    let strings = run_native_workers_text(stores, &input, elem_size, threads, n, &worker);
    stores.par_text_buffer_stack.push(strings);
    n as i64
}

/// Plan-06 spine step 8d.1 (native variant) — heap-ref-return Queue.
/// Allocates a single result store, deep-copies each worker-side
/// struct return into a row-indexed slot, and pushes
/// `(row_refs, [result_store_nr])` onto `par_ref_buffer_stack`.  The
/// adopted-store list lets `n_parallel_buf_drop_ref_native` free the
/// result store when the loop body completes.
///
/// Simpler than the interpreter's adoption-via-rebase machinery:
/// each row is a record at offset `i * struct_size` inside one
/// owned store, instead of a per-worker store with rebase translation.
/// The cost: one `copy_from_worker[_unowned]` per row.  The benefit:
/// no `worker_allocated_indices` / `StoreRebase` / dispenser plumbing
/// in the native path.
pub fn n_parallel_queue_ref_native<F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    elem_size: i32,
    struct_size: i32,
    known_type: i32,
    threads: i32,
    worker: F,
) -> i64
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> DbRef + Send + Sync,
{
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let n = vector::length_vector(&input, &stores.allocations) as usize;
    let sz = struct_size as u32;
    let kt = known_type as u16;

    if n == 0 {
        stores.par_ref_buffer_stack.push((Vec::new(), Vec::new()));
        return 0;
    }

    // Reserve one leading element slot so no result lands at `pos == 0`: a vector
    // (and every keyed collection) reads `pos == 0` as its null/empty sentinel
    // (`vector::length_vector`), so an element stored there would always read as
    // empty.  Structs have no such sentinel, but the uniform `+1` offset is
    // harmless for them — every `refs[i]` carries its true position to the reader.
    let result_db = stores.null();
    let total_words = ((n as u32 + 1) * sz).div_ceil(8).max(1);
    let result_cr = stores.claim(&result_db, total_words);
    let result_store_nr = result_db.store_nr;
    let result_rec = result_cr.rec;

    let batches = run_native_workers_ref(stores, &input, elem_size, threads, n, &worker);

    let unowned = !stores.has_owned_sub_fields(kt);
    let mut refs: Vec<DbRef> = vec![DbRef::NULL; n];
    for (batch, mut worker_stores) in batches {
        for (i, src_ref) in batch {
            let dest = DbRef {
                store_nr: result_store_nr,
                rec: result_rec,
                pos: (i as u32 + 1) * sz,
            };
            if unowned {
                stores.copy_from_worker_unowned(&src_ref, &dest, &mut worker_stores, kt);
            } else {
                stores.copy_from_worker(&src_ref, &dest, &mut worker_stores, kt);
            }
            refs[i] = dest;
        }
    }

    stores
        .par_ref_buffer_stack
        .push((refs, vec![result_store_nr]));
    n as i64
}

/// Read a row from the active scalar par-buffer.  The buffer is a
/// `Vec<u64>` (workers' bit-cast returns); narrow returns leave the
/// high bits zero.  Caller masks to the actual return width.
///
/// # Panics
/// Panics if `par_buffer_stack` is empty (no active scalar queue) or
/// if `idx` is out of range — both indicate a parser-side bug.
pub fn n_parallel_buf_get_native(cell: &std::cell::UnsafeCell<Stores>, idx: i64) -> i64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let buf = stores
        .par_buffer_stack
        .last()
        .expect("n_parallel_buf_get_native: par_buffer_stack is empty");
    buf[idx as usize] as i64
}

/// Plan-06 ARC.md A3 (native variant) — narrow-Integer Queue.
/// Workers return narrow integers (i8/i16/i32/u8/u16); each return
/// is i64-promoted on the worker stack and cast `as i64` by the
/// emitter's closure.  Pack each into the low `stride` bytes of a
/// `Vec<u8>` and push onto `par_narrow_buffer_stack`.
///
/// # Panics
/// Panics if `return_size` is not 1, 2, or 4 — the parser-side
/// gate filters narrow Integer returns to those widths.
pub fn n_parallel_queue_narrow_native<F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    elem_size: i32,
    return_size: i32,
    threads: i32,
    worker: F,
) -> i64
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> i64 + Send + Sync,
{
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let n = vector::length_vector(&input, &stores.allocations) as usize;
    let stride = match return_size {
        1 | 2 | 4 => return_size as u8,
        other => {
            panic!("n_parallel_queue_narrow_native: invalid return_size {other} (expected 1/2/4)")
        }
    };
    let results = run_native_workers_primitive(stores, &input, elem_size, threads, n, &worker);
    let mut bytes = Vec::with_capacity(n * stride as usize);
    for v in &results {
        let row_bytes = v.to_le_bytes();
        bytes.extend_from_slice(&row_bytes[..stride as usize]);
    }
    stores.par_narrow_buffer_stack.push((bytes, stride));
    n as i64
}

/// Plan-06 ARC.md A3 (native variant) — read one narrow row.
/// `return_size` must equal the stride pushed by
/// `n_parallel_queue_narrow_native`; `signed` selects sign-extension
/// (passed as `i64` 0/1 since the emit path passes the loft-side
/// `boolean → integer 0/1` rendering).
///
/// # Panics
/// Panics if `par_narrow_buffer_stack` is empty, if `return_size`
/// doesn't match the stored stride, or if `idx` is out of range —
/// all indicate parser-side bugs.
pub fn n_parallel_buf_get_narrow_native(
    cell: &std::cell::UnsafeCell<Stores>,
    idx: i64,
    return_size: i64,
    signed: i64,
) -> i64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let entry = stores
        .par_narrow_buffer_stack
        .last()
        .expect("n_parallel_buf_get_narrow_native: par_narrow_buffer_stack is empty");
    let stride = entry.1 as usize;
    debug_assert_eq!(
        stride, return_size as usize,
        "n_parallel_buf_get_narrow_native: stride/return_size mismatch (stride={stride}, arg={return_size})"
    );
    let off = (idx as usize) * stride;
    let bytes = &entry.0;
    let signed = signed != 0;
    match (stride, signed) {
        (1, false) => i64::from(bytes[off]),
        (1, true) => i64::from(bytes[off] as i8),
        (2, false) => i64::from(u16::from_le_bytes([bytes[off], bytes[off + 1]])),
        (2, true) => i64::from(i16::from_le_bytes([bytes[off], bytes[off + 1]])),
        (4, false) => i64::from(u32::from_le_bytes([
            bytes[off],
            bytes[off + 1],
            bytes[off + 2],
            bytes[off + 3],
        ])),
        (4, true) => i64::from(i32::from_le_bytes([
            bytes[off],
            bytes[off + 1],
            bytes[off + 2],
            bytes[off + 3],
        ])),
        _ => panic!("n_parallel_buf_get_narrow_native: invalid stride {stride}"),
    }
}

/// Plan-06 ARC.md A3.6 (native variant) — typed reader for `single`
/// (f32) returns from `n_parallel_queue_narrow_native` (stride 4).
/// Reads the same per-row bytes as `n_parallel_buf_get_narrow_native`
/// but interprets them as a 4-byte f32 bit pattern via
/// `f32::from_bits` instead of returning an i64 the caller would
/// then have to bit-cast.  Mirrors the interpreter-side
/// `n_parallel_buf_get_single` in `src/native.rs`.
///
/// # Panics
/// Panics if `par_narrow_buffer_stack` is empty, if the stride isn't
/// 4, or if `idx` is out of range — all indicate parser-side bugs.
pub fn n_parallel_buf_get_single_native(cell: &std::cell::UnsafeCell<Stores>, idx: i64) -> f32 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let entry = stores
        .par_narrow_buffer_stack
        .last()
        .expect("n_parallel_buf_get_single_native: par_narrow_buffer_stack is empty");
    let stride = entry.1 as usize;
    debug_assert_eq!(
        stride, 4,
        "n_parallel_buf_get_single_native: stride must be 4 (got {stride})"
    );
    let off = (idx as usize) * stride;
    let bytes = &entry.0;
    let raw = u32::from_le_bytes([bytes[off], bytes[off + 1], bytes[off + 2], bytes[off + 3]]);
    f32::from_bits(raw)
}

/// Plan-06 ARC.md A3.6 (native variant) — typed reader for `float`
/// (f64) returns from `n_parallel_queue_native` (wide u64 rows).
/// Reads the same per-row u64 as `n_parallel_buf_get_native` but
/// interprets the bits as f64 via `f64::from_bits`.  Mirrors the
/// interpreter-side `n_parallel_buf_get_float` in `src/native.rs`.
///
/// # Panics
/// Panics if `par_buffer_stack` is empty or `idx` is out of range —
/// both indicate parser-side bugs.
pub fn n_parallel_buf_get_float_native(cell: &std::cell::UnsafeCell<Stores>, idx: i64) -> f64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let row = stores
        .par_buffer_stack
        .last()
        .expect("n_parallel_buf_get_float_native: par_buffer_stack is empty")[idx as usize];
    f64::from_bits(row)
}

/// Plan-06 ARC.md A3 (native variant) — pop the active narrow
/// par-buffer.
///
/// # Panics
/// Panics if `par_narrow_buffer_stack` is already empty.
pub fn n_parallel_buf_drop_narrow_native(cell: &std::cell::UnsafeCell<Stores>) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores
        .par_narrow_buffer_stack
        .pop()
        .expect("n_parallel_buf_drop_narrow_native: par_narrow_buffer_stack is already empty");
}

/// Read a row from the active text par-buffer.  Stages the `String`
/// into `stores.scratch` so the returned `Str` borrow remains valid
/// across the call (mirrors the interpreter's text-return convention).
///
/// # Panics
/// Panics if `par_text_buffer_stack` is empty (no active text queue)
/// or if `idx` is out of range — both indicate a parser-side bug.
// @PLN10 — owned `String` (no scratch); in lockstep with
// `generation::native_returns_owned_string` (`n_parallel_buf_get_text`).
pub fn n_parallel_buf_get_text_native(cell: &std::cell::UnsafeCell<Stores>, idx: i64) -> String {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let buf = stores
        .par_text_buffer_stack
        .last()
        .expect("n_parallel_buf_get_text_native: par_text_buffer_stack is empty");
    buf[idx as usize].clone()
}

/// Read a row from the active ref par-buffer.  Returns the per-row
/// `DbRef` pointing into the result store this queue allocated.  The
/// caller's field reads go through that store; the store stays
/// adopted until `n_parallel_buf_drop_ref_native` fires.
///
/// # Panics
/// Panics if `par_ref_buffer_stack` is empty (no active ref queue) or
/// if `idx` is out of range — both indicate a parser-side bug.
pub fn n_parallel_buf_get_ref_native(cell: &std::cell::UnsafeCell<Stores>, idx: i64) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let (refs, _) = stores
        .par_ref_buffer_stack
        .last()
        .expect("n_parallel_buf_get_ref_native: par_ref_buffer_stack is empty");
    refs[idx as usize]
}

/// Pop the active scalar par-buffer.  Called after the loop body
/// completes.
///
/// # Panics
/// Panics if `par_buffer_stack` is already empty — indicates a
/// parser-side bug (drop emitted without a matching queue).
pub fn n_parallel_buf_drop_native(cell: &std::cell::UnsafeCell<Stores>) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores
        .par_buffer_stack
        .pop()
        .expect("n_parallel_buf_drop_native: par_buffer_stack is already empty");
}

/// Pop the active text par-buffer.
///
/// # Panics
/// Panics if `par_text_buffer_stack` is already empty — indicates a
/// parser-side bug (drop emitted without a matching queue_text).
pub fn n_parallel_buf_drop_text_native(cell: &std::cell::UnsafeCell<Stores>) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores
        .par_text_buffer_stack
        .pop()
        .expect("n_parallel_buf_drop_text_native: par_text_buffer_stack is already empty");
}

/// Pop the active ref par-buffer + free its adopted result store.
///
/// # Panics
/// Panics if `par_ref_buffer_stack` is already empty — indicates a
/// parser-side bug (drop emitted without a matching queue_ref).
pub fn n_parallel_buf_drop_ref_native(cell: &std::cell::UnsafeCell<Stores>) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let (_refs, adopted) = stores
        .par_ref_buffer_stack
        .pop()
        .expect("n_parallel_buf_drop_ref_native: par_ref_buffer_stack is already empty");
    for store_nr in adopted {
        let synthetic = DbRef {
            store_nr,
            rec: 0,
            pos: 0,
        };
        stores.free_named(&synthetic, "par_buf_drop_ref");
    }
}

// ── #281 — native fn-ref-return Queue ───────────────────────────────────────
//
// A par worker that returns a function reference yields the native fn-ref value
// `(u32 d_nr, DbRef closure)`.  These three fns mirror the scalar/ref queue
// family: run the worker closures, buffer one `(u32, DbRef)` per row in
// `par_fn_native_buffer_stack`, and let the body read each back.  The
// interpreter's `n_parallel_*_fn` use a byte-packed 20-byte buffer; the native
// path stays typed (no serialization) since it owns both ends.

/// Per-row worker driver for the fn-ref Queue — mirrors
/// `run_native_workers_primitive` but collects the worker's `(u32, DbRef)`
/// fn-ref return per row.
fn run_native_workers_fn<F>(
    stores: &Stores,
    input: &DbRef,
    elem_size: i32,
    n_threads: i32,
    n: usize,
    worker: &F,
) -> Vec<(u32, DbRef)>
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> (u32, DbRef) + Send + Sync,
{
    if n == 0 {
        return Vec::new();
    }
    let input_t = *input;
    let n_threads = n_threads.max(1) as usize;
    let batches = crate::parallel::parallel_workers(stores, n_threads, n, |start, end, mut ws| {
        let mut local: Vec<(u32, DbRef)> = Vec::with_capacity(end - start);
        for row_idx in start..end {
            let elm =
                vector::get_vector(&input_t, elem_size as u32, row_idx as i64, &ws.allocations);
            let cell: &std::cell::UnsafeCell<Stores> =
                unsafe { &*(&raw mut ws.stores as *const std::cell::UnsafeCell<Stores>) };
            local.push(worker(cell, elm));
        }
        (start, local)
    });
    let null_fn = (u32::MAX, DbRef::NULL);
    crate::parallel::merge_batches(batches, n, null_fn)
}

/// fn-ref-return Queue runtime entry — runs workers, buffers one `(u32, DbRef)`
/// per row on `par_fn_native_buffer_stack`, returns the row count.
pub fn n_parallel_queue_fn_native<F>(
    cell: &std::cell::UnsafeCell<Stores>,
    input: DbRef,
    elem_size: i32,
    _return_size: i32,
    threads: i32,
    worker: F,
) -> i64
where
    F: Fn(&std::cell::UnsafeCell<Stores>, DbRef) -> (u32, DbRef) + Send + Sync,
{
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let n = vector::length_vector(&input, &stores.allocations) as usize;
    let results = run_native_workers_fn(stores, &input, elem_size, threads, n, &worker);
    stores.par_fn_native_buffer_stack.push(results);
    n as i64
}

/// Read row `idx`'s fn-ref `(u32, DbRef)` from the active fn-ref Queue buffer.
///
/// # Panics
/// Panics if no fn-ref Queue is active (`par_fn_native_buffer_stack` empty) or
/// `idx` is out of range — both indicate a parser-side bug, not reachable from
/// valid loft source.
pub fn n_parallel_buf_get_fn_native(
    cell: &std::cell::UnsafeCell<Stores>,
    idx: i64,
) -> (u32, DbRef) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let buf = stores
        .par_fn_native_buffer_stack
        .last()
        .expect("n_parallel_buf_get_fn_native: par_fn_native_buffer_stack is empty");
    buf[idx as usize]
}

/// Pop the active fn-ref Queue buffer after the loop body completes.
///
/// # Panics
/// Panics if the buffer stack is already empty (a drop without a matching
/// queue — parser-side bug).
pub fn n_parallel_buf_drop_fn_native(cell: &std::cell::UnsafeCell<Stores>) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores
        .par_fn_native_buffer_stack
        .pop()
        .expect("n_parallel_buf_drop_fn_native: par_fn_native_buffer_stack is already empty");
}

// ── N8b.1: Native coroutine runtime ─────────────────────────────────────────

/// Sentinel `store_nr` for `DbRef`s that point to native coroutine generators.
/// Must not clash with any real `Stores` allocation (stores use 0..`Stores::max`).
pub const NATIVE_COROUTINE_STORE: u16 = 0xFFFD;

/// Return value from `LoftCoroutine::next_i64` when the generator is exhausted.
///
/// Post-2c the `integer` type is i64 — both integer- and long-yielding
/// generators terminate on `op_conv_bool_from_int(val)` returning
/// `false`, which happens exactly when `val == i64::MIN`.  Pre-2c this
/// constant was `i32::MIN as i64` because the integer null sentinel was
/// `i32::MIN`; that's now the wrong value — the sentinel moved to
/// `i64::MIN` when Phase 2c widened integer storage, and
/// `coroutine_next_i64` returning `i32::MIN as i64` was being
/// interpreted as a real value by `op_conv_bool_from_int`, leaving the
/// for-loop iterating forever.
pub const COROUTINE_EXHAUSTED: i64 = i64::MIN;

/// Trait implemented by every native generator (state-machine struct).
/// The generated `fn {name}(stores, args) -> Box<dyn LoftCoroutine>` factory
/// constructs an instance; `alloc_coroutine` stores it and returns a `DbRef`.
///
/// One method per yielded primitive shape:
/// - `next_i64` for integer / float / boolean / single / character yields
///   (everything that fits in 8 bytes).
/// - `next_text` for `text` yields.  Returns `STRING_NULL` ("\0") on
///   exhaustion, matching the for-loop break-test convention used by
///   `dispatch.rs::OpCoroutineNext`.
///
/// A given generator only ever overrides the method matching its yield
/// type; the other keeps its default (returns the type's exhaustion
/// sentinel) so a wrong-channel call drains the loop immediately rather
/// than panicking.
pub trait LoftCoroutine {
    /// Advance an integer-yielding generator one step.  Returns the yielded
    /// value as `i64`, or `COROUTINE_EXHAUSTED` when no further values are
    /// available.
    fn next_i64(&mut self, _stores: &mut Stores) -> i64 {
        COROUTINE_EXHAUSTED
    }

    /// Advance a text-yielding generator one step.  Returns the yielded
    /// `String`, or `STRING_NULL` (`"\0"`) when the generator is exhausted.
    fn next_text(&mut self, _stores: &mut Stores) -> String {
        crate::state::STRING_NULL.to_string()
    }

    /// Advance a Reference-yielding generator one step.  Returns the yielded
    /// `DbRef`, or the null-DbRef sentinel (`store_nr == u16::MAX`, `rec == 0`)
    /// when the generator is exhausted.  Used by `iterator<Struct>` /
    /// `iterator<vector<T>>` / any DbRef-shaped yield (@P326).
    fn next_dbref(&mut self, _stores: &mut Stores) -> DbRef {
        DbRef::NULL
    }

    /// Unified store-backed yield channel (@P327 native; designed to absorb
    /// future yield shapes without adding one trait method per shape — see
    /// `plans/16-coroutine-validation/01-unified-channel.md`).  Advance the
    /// generator one step and write the yielded value's bytes into `dest`
    /// (a caller-provided `i64`-aligned buffer sized for the yielded type).
    /// Returns true on yield, false on exhaustion.
    ///
    /// Each coroutine impl encodes its OWN yield-type layout in this single
    /// method — no new trait method per shape.  This is the migration
    /// target for `next_i64` / `next_dbref` / `next_text`; each can move
    /// to `next_into` one shape at a time.
    fn next_into(&mut self, _stores: &mut Stores, _dest: &mut [i64]) -> bool {
        false
    }

    /// Release the heap locals this generator still owns.
    ///
    /// A generator frees its own locals from the tail of its body, and a consumer that
    /// stops early never reaches that tail — so an abandoned generator's vector stayed
    /// allocated for the rest of the program (loft#835).  Called when the handle is freed
    /// at the end of the scope holding it.  Generated per generator; a generator with no
    /// owned heap local keeps this no-op default.
    ///
    /// Freeing twice is not possible: every scope-exit free the generator DOES run nulls
    /// its own field, and the generated body only frees fields that are still set.
    fn drop_stores(&mut self, _stores: &mut Stores) {}
}

std::thread_local! {
    /// Per-thread storage for native coroutine instances, each tagged with the generation
    /// that identifies THIS occupant of the slot.  Slot 0 is always `None` (null sentinel).
    ///
    /// A slot is freed on exhaustion and handed to the next generator, while the variable
    /// holding the handle lives to the end of its scope, where its free fires — so the
    /// index alone does not identify a coroutine for long enough.  Mirrors
    /// `CoroutineFrame::generation` on the interpreter side.
    static NATIVE_COROUTINES: std::cell::RefCell<Vec<Option<(u32, Box<dyn LoftCoroutine>)>>> =
        std::cell::RefCell::new(vec![None]);
    /// Stamp handed to the next coroutine allocated on this thread.
    static NATIVE_COROUTINE_GENERATION: std::cell::Cell<u32> = const { std::cell::Cell::new(1) };
}

/// Does `gen_ref` still name the frame it was made for — right slot AND right occupant?
fn native_coroutine_live(
    coroutines: &[Option<(u32, Box<dyn LoftCoroutine>)>],
    gen_ref: DbRef,
) -> bool {
    gen_ref.store_nr == NATIVE_COROUTINE_STORE
        && gen_ref.rec != 0
        && coroutines
            .get(gen_ref.rec as usize)
            .and_then(Option::as_ref)
            .is_some_and(|(generation, _)| *generation == gen_ref.pos)
}

/// Store a native coroutine generator and return a `DbRef` that identifies it.
///
/// `pos` carries the generation stamp: a coroutine reference addresses no store, so the
/// field is free, and the handle then names the generator rather than the index it occupies.
#[must_use]
pub fn alloc_coroutine(coro: Box<dyn LoftCoroutine>) -> DbRef {
    let generation = NATIVE_COROUTINE_GENERATION.with(|g| {
        let cur = g.get();
        g.set(cur.wrapping_add(1).max(1));
        cur
    });
    NATIVE_COROUTINES.with(|c| {
        let mut coroutines = c.borrow_mut();
        for (i, slot) in coroutines.iter_mut().enumerate().skip(1) {
            if slot.is_none() {
                *slot = Some((generation, coro));
                return DbRef {
                    store_nr: NATIVE_COROUTINE_STORE,
                    rec: i as u32,
                    pos: generation,
                };
            }
        }
        let idx = coroutines.len();
        coroutines.push(Some((generation, coro)));
        DbRef {
            store_nr: NATIVE_COROUTINE_STORE,
            rec: idx as u32,
            pos: generation,
        }
    })
}

/// Free one heap local an abandoned generator still owns (loft#835).
///
/// A nested generator handle routes back to the coroutine table so its own locals are
/// released too; anything else is an ordinary store.  Called only from a generated
/// `drop_stores`, which has already checked the field is set.
pub fn coroutine_drop_local(stores: &mut Stores, db: DbRef, name: &str) {
    if db.store_nr == NATIVE_COROUTINE_STORE {
        free_native_coroutine(db, stores);
    } else if db.store_nr != u16::MAX && (db.store_nr as usize) < stores.allocations.len() {
        stores.free_named(&db, name);
    }
}

/// Copy the `tp` record `src` into the generator's snapshot store `snap` and answer the
/// copy's handle.  An eager factory runs its whole loop before the consumer reads a
/// value, so a pushed handle to a per-iteration local would alias the local's FINAL
/// state; the copy pins the value as it was at the yield.  One store per generator —
/// allocated by the first snapshot, every later one a record claimed in it — so a long
/// loop costs records, not store slots.  A null yield stays null.
pub fn coroutine_snapshot(
    cell: &std::cell::UnsafeCell<Stores>,
    snap: &mut DbRef,
    src: DbRef,
    tp: i32,
) -> DbRef {
    if src.store_nr == u16::MAX {
        return src;
    }
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let tp = tp as u16;
    if snap.store_nr == u16::MAX {
        *snap = stores.null();
        stores.clear(snap);
        stores.allocations[snap.store_nr as usize].set_known_type(tp);
    }
    // Same record shape `OpDatabase` claims: a word of header, then `size` bytes.
    let size = stores.enum_parent_size(tp);
    let r = stores.claim(snap, 1 + u32::from(size).div_ceil(8));
    stores.store_mut(&r).set_u32_raw(r.rec, 4, u32::from(tp));
    stores.set_default_value(tp, &r);
    OpCopyRecord(cell, src, r, i32::from(tp));
    r
}

/// Release a generator's snapshot store (see [`coroutine_snapshot`]) — at exhaustion,
/// and from `drop_stores` when the generator is abandoned.  Idempotent.
pub fn coroutine_release_snapshots(stores: &mut Stores, snap: &mut DbRef) {
    if snap.store_nr != u16::MAX && (snap.store_nr as usize) < stores.allocations.len() {
        stores.free_named(snap, "__snap");
    }
    *snap = DbRef::NULL;
}

/// Free a native coroutine handle: release the heap locals the generator still owns, then
/// its slot.  A handle whose generator already exhausted names a frame that is gone, and
/// the generation check keeps this off whatever inherited the slot (loft#835).
pub fn free_native_coroutine(gen_ref: DbRef, stores: &mut Stores) {
    // Take the generator OUT of the table before running its cleanup: `drop_stores` frees
    // stores, and a nested generator handle among them re-enters this table.
    let taken = NATIVE_COROUTINES.with(|c| {
        let mut coroutines = c.borrow_mut();
        if native_coroutine_live(&coroutines, gen_ref) {
            coroutines[gen_ref.rec as usize].take()
        } else {
            None
        }
    });
    if let Some((_, mut coro)) = taken {
        coro.drop_stores(stores);
    }
}

/// Advance a native coroutine and return the yielded value as `i64`.
/// Frees the coroutine slot automatically when it is exhausted.
pub fn coroutine_next_i64(gen_ref: DbRef, stores: &mut Stores) -> i64 {
    NATIVE_COROUTINES.with(|c| {
        let mut coroutines = c.borrow_mut();
        let idx = gen_ref.rec as usize;
        if native_coroutine_live(&coroutines, gen_ref)
            && let Some((_, coro)) = coroutines[idx].as_mut()
        {
            let val = coro.next_i64(stores);
            if val == COROUTINE_EXHAUSTED {
                coroutines[idx] = None; // free on exhaustion (P2-R7 parity)
            }
            val
        } else {
            COROUTINE_EXHAUSTED
        }
    })
}

/// Advance a generator through the unified store-backed yield channel
/// (@P327 native).  Writes the yielded value's bytes into `dest` and
/// returns true; returns false and frees the slot on exhaustion.
pub fn coroutine_next_into(gen_ref: DbRef, stores: &mut Stores, dest: &mut [i64]) -> bool {
    NATIVE_COROUTINES.with(|c| {
        let mut coroutines = c.borrow_mut();
        let idx = gen_ref.rec as usize;
        if native_coroutine_live(&coroutines, gen_ref)
            && let Some((_, coro)) = coroutines[idx].as_mut()
        {
            let ok = coro.next_into(stores, dest);
            if !ok {
                coroutines[idx] = None;
            }
            ok
        } else {
            false
        }
    })
}

/// Advance a Reference-yielding native coroutine.  Returns the yielded
/// `DbRef`, or the null-DbRef sentinel (store_nr=u16::MAX, rec=0) when
/// exhausted.  Frees the coroutine slot automatically on exhaustion,
/// mirroring `coroutine_next_i64` (@P326).
pub fn coroutine_next_dbref(gen_ref: DbRef, stores: &mut Stores) -> DbRef {
    NATIVE_COROUTINES.with(|c| {
        let mut coroutines = c.borrow_mut();
        let idx = gen_ref.rec as usize;
        if native_coroutine_live(&coroutines, gen_ref)
            && let Some((_, coro)) = coroutines[idx].as_mut()
        {
            let val = coro.next_dbref(stores);
            // Null sentinel matches `vector::null_ref` and `OpNullRefSentinel`:
            // store_nr == u16::MAX is the universal "no record" indicator.
            // The for-loop's `OpCoroutineExhausted(gen)` check also flips to
            // true here because exhaustion frees the slot.
            if val.store_nr == u16::MAX {
                coroutines[idx] = None;
            }
            val
        } else {
            DbRef::NULL
        }
    })
}

/// Advance a text-yielding native coroutine.  Returns the yielded `String`,
/// or `STRING_NULL` (`"\0"`) when exhausted.  Frees the coroutine slot
/// automatically on exhaustion, mirroring `coroutine_next_i64`.
pub fn coroutine_next_text(gen_ref: DbRef, stores: &mut Stores) -> String {
    NATIVE_COROUTINES.with(|c| {
        let mut coroutines = c.borrow_mut();
        let idx = gen_ref.rec as usize;
        if native_coroutine_live(&coroutines, gen_ref)
            && let Some((_, coro)) = coroutines[idx].as_mut()
        {
            let val = coro.next_text(stores);
            if val == crate::state::STRING_NULL {
                coroutines[idx] = None;
            }
            val
        } else {
            crate::state::STRING_NULL.to_string()
        }
    })
}

/// Test whether a native coroutine has been exhausted (its slot freed).
#[must_use]
pub fn coroutine_is_exhausted(gen_ref: DbRef) -> bool {
    NATIVE_COROUTINES.with(|c| {
        let coroutines = c.borrow();
        !native_coroutine_live(&coroutines, gen_ref)
    })
}

// ── FS-B  File-system dispatch helpers ───────────────────────────────────────
// Called from fill.rs (interpreter) and generated native code alike.
// Paths: interpreter uses `crate::codegen_runtime::*`; native uses
// `use loft::codegen_runtime::*` so these names resolve in both contexts.
// Under `host_fs` (the wasm-bindgen bundle, and `--html`) each function calls
// the host bridge; otherwise it calls the real filesystem.

// Filesystem-op result codes shared by the interpreter and the native runtime.
// The `default/02_files.loft` wrappers map these to `FileResult` variants via an
// explicit `match`, so the codes are deliberately decoupled from the enum's
// declaration order — reordering the loft enum can never silently remap a code.
const FS_OK: i64 = 0;
const FS_OTHER: i64 = 9;
// Ungated: the `*_at` wrappers answer `NotFound` for a path outside the project
// on every target, so this code is reachable in the wasm build too (loft#708).
const FS_NOT_FOUND: i64 = 1;
#[cfg(not(host_fs))]
const FS_PERMISSION_DENIED: i64 = 2;
#[cfg(not(host_fs))]
const FS_IS_DIRECTORY: i64 = 3;
// loft#1256 — `rmdir` refused because the directory still holds entries.  Its own code
// because it is the one failure a caller can ACT on: empty the directory and retry.  Folding
// it into `FS_OTHER` would leave the only recoverable case indistinguishable from the
// unrecoverable ones.
#[cfg(not(host_fs))]
const FS_NOT_EMPTY: i64 = 4;

/// Classify a filesystem mutation's result into an `FS_*` code.  `dir_is_err`
/// asks for the "target is a directory" failure to be reported as
/// `FS_IS_DIRECTORY` (true for `remove_file`, which refuses directories); it is
/// detected by a portable `fs_is_dir` stat rather than `ErrorKind::IsADirectory`,
/// which only stabilised in Rust 1.83 and this file is recompiled by the user's
/// rustc for `--native`.
#[cfg(not(host_fs))]
fn fs_classify(r: std::io::Result<()>, path: &str, dir_is_err: bool) -> i64 {
    match r {
        Ok(()) => FS_OK,
        Err(e) => {
            // "target is a directory" must be checked BEFORE PermissionDenied: Linux
            // reports `remove_file` on a directory as EISDIR, but macOS/BSD report it as
            // EPERM (→ ErrorKind::PermissionDenied).  Consulting the portable `fs_is_dir`
            // stat first makes a directory target classify as FS_IS_DIRECTORY uniformly,
            // instead of leaking the platform's errno (a real EPERM on a *file* still
            // falls through, because `fs_is_dir` is false for it and for a missing path).
            if dir_is_err && fs_is_dir(path) {
                return FS_IS_DIRECTORY;
            }
            match e.kind() {
                std::io::ErrorKind::NotFound => FS_NOT_FOUND,
                std::io::ErrorKind::PermissionDenied => FS_PERMISSION_DENIED,
                _ => FS_OTHER,
            }
        }
    }
}

/// Remove the EMPTY directory `path`.  Returns an `FS_*` code (mapped to `FileResult` by the
/// `rmdir` wrapper).
///
/// Empty directories only, deliberately: a recursive removal is the sharpest tool a
/// filesystem API has, and it deserves its own decision rather than arriving inside the
/// primitive that closes the create/remove asymmetry.  A caller that wants one writes the
/// walk with `list_dir` and this.
///
/// "Not empty" is detected by STATTING rather than by `ErrorKind::DirectoryNotEmpty`, for the
/// reason the `IsADirectory` comment above gives: that variant stabilised in Rust 1.83, and
/// this file is recompiled by the USER's rustc for `--native`.  The kind is consulted first
/// so a genuine permission error on a non-empty directory keeps its own answer.
pub fn fs_rmdir(path: &str) -> i64 {
    #[cfg(host_fs)]
    {
        // The browser host bridges `mkdir` but has no `rmdir` counterpart, so this refuses
        // rather than reporting a removal that did not happen — `FileResult.Other`, which the
        // enum's own doc already names as the wasm host's catch-all.
        let _ = path;
        FS_OTHER
    }
    #[cfg(not(host_fs))]
    {
        match std::fs::remove_dir(path) {
            Ok(()) => FS_OK,
            Err(e) => match e.kind() {
                std::io::ErrorKind::NotFound => FS_NOT_FOUND,
                std::io::ErrorKind::PermissionDenied => FS_PERMISSION_DENIED,
                _ if fs_is_dir(path)
                    && std::fs::read_dir(path).is_ok_and(|mut d| d.next().is_some()) =>
                {
                    FS_NOT_EMPTY
                }
                _ => FS_OTHER,
            },
        }
    }
}

/// Delete file `path`.  Returns an `FS_*` code (mapped to `FileResult` by the
/// `delete` wrapper).  A directory target yields `FS_IS_DIRECTORY`.
pub fn fs_delete(path: &str) -> i64 {
    #[cfg(host_fs)]
    {
        if crate::wasm::host_fs_delete(path) == 0 {
            FS_OK
        } else {
            FS_OTHER
        }
    }
    #[cfg(not(host_fs))]
    {
        fs_classify(std::fs::remove_file(path), path, true)
    }
}

/// Rename / move `from` to `to`.  Returns an `FS_*` code.
#[must_use]
pub fn fs_move(from: &str, to: &str) -> i64 {
    #[cfg(host_fs)]
    {
        if crate::wasm::host_fs_move(from, to) == 0 {
            FS_OK
        } else {
            FS_OTHER
        }
    }
    #[cfg(not(host_fs))]
    {
        fs_classify(std::fs::rename(from, to), from, false)
    }
}

/// Create directory `path`.  Returns an `FS_*` code.
#[must_use]
pub fn fs_mkdir(path: &str) -> i64 {
    #[cfg(host_fs)]
    {
        if crate::wasm::host_fs_mkdir(path) == 0 {
            FS_OK
        } else {
            FS_OTHER
        }
    }
    #[cfg(not(host_fs))]
    {
        fs_classify(std::fs::create_dir(path), path, false)
    }
}

/// Create directory `path` and all parents.  Returns an `FS_*` code.
#[must_use]
pub fn fs_mkdir_all(path: &str) -> i64 {
    #[cfg(host_fs)]
    {
        if crate::wasm::host_fs_mkdir_all(path) == 0 {
            FS_OK
        } else {
            FS_OTHER
        }
    }
    #[cfg(not(host_fs))]
    {
        fs_classify(std::fs::create_dir_all(path), path, false)
    }
}

/// Returns `true` if `path` exists and is a directory.
#[must_use]
pub fn fs_is_dir(path: &str) -> bool {
    #[cfg(host_fs)]
    {
        crate::wasm::host_fs_is_dir(path)
    }
    #[cfg(not(host_fs))]
    {
        std::path::Path::new(path).is_dir()
    }
}

/// Returns `true` if `path` exists and is a regular file.
#[must_use]
pub fn fs_is_file(path: &str) -> bool {
    #[cfg(host_fs)]
    {
        crate::wasm::host_fs_is_file(path)
    }
    #[cfg(not(host_fs))]
    {
        std::path::Path::new(path).is_file()
    }
}

/// Store a closure DbRef associated with a lambda definition number.
/// Called in generated native code when `OpStoreClosure` appears in the IR,
/// immediately before the fn-ref variable is stored.
/// The closure is later retrieved by `OpGetClosure` in the match-dispatch arm.
pub fn OpStoreClosure(cell: &std::cell::UnsafeCell<Stores>, d_nr: u32, closure: DbRef) {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores.closure_map.insert(d_nr, closure);
}

/// Retrieve the closure DbRef for a lambda definition number.
/// Called in generated native code inside match-dispatch arms for closure-capturing lambdas.
/// Returns a null DbRef if no closure was registered for `d_nr`.
#[must_use]
pub fn OpGetClosure(cell: &std::cell::UnsafeCell<Stores>, d_nr: u32) -> DbRef {
    let stores: &Stores = unsafe { &*cell.get() };
    stores.closure_map.get(&d_nr).copied().unwrap_or(DbRef {
        store_nr: 0,
        rec: 0,
        pos: 0,
    })
}

// ── Shadow call stack for native stack_trace() ──────────────────────────────

/// loft#950 — make a Rust panic in a browser (`--html`) build say what it was.
///
/// On `wasm32-unknown-unknown` a panic aborts, and abort compiles to the `unreachable`
/// instruction — so the page's only symptom is `RuntimeError: unreachable`.  The message
/// std would have printed goes to that target's stderr, which is a sink, so the trap
/// arrives with no name, no location and no stack.  That is what made loft#950
/// undebuggable from the browser: the consumer could see WHERE in their own transcript
/// the page died, and nothing whatever about why.
///
/// The hook forwards the panic — message and `file:line` — through the same host import
/// `println` uses, so it lands in the page's console before the trap.  Called from the
/// generated `loft_start`, ahead of `init`, so a panic during startup is covered too.
///
/// It does NOT cover an allocation failure: `handle_alloc_error` aborts without running
/// the panic hook.  That is worth knowing rather than worth fixing — a trap that stays
/// silent after this has told you it was not a panic.
///
/// A no-op on every other target, where stderr works and the native crash reporter
/// already owns this job.
pub fn install_browser_panic_hook() {
    #[cfg(all(target_arch = "wasm32", not(target_os = "wasi"), not(feature = "wasm")))]
    {
        use std::sync::atomic::{AtomicBool, Ordering};
        static INSTALLED: AtomicBool = AtomicBool::new(false);
        if INSTALLED.swap(true, Ordering::SeqCst) {
            return;
        }
        std::panic::set_hook(Box::new(|info| {
            // `PanicHookInfo`'s own Display is "panicked at <file:line:col>:\n<payload>",
            // which is the whole of what the default hook would have written to stderr.
            let mut out = format!("loft: {info}\n");
            // …plus the LOFT frames it happened under.  The Rust location alone names a
            // spot in generated code or in loft's own runtime, which does not say what
            // the program was doing; the shadow call stack is the half a reader acts on.
            out.push_str(&browser_panic_frames());
            crate::live_dispatch::wasm_host_log(&out);
        }));
    }
}

/// The loft frames a browser panic happened under, innermost first, as indented lines.
///
/// `try_borrow` rather than `borrow`: a panic can fire while the shadow stack is already
/// borrowed, and a hook that panics in turn loses the message it exists to deliver.
/// Missing frames are worth strictly less than the message, so they yield.
#[cfg(all(target_arch = "wasm32", not(target_os = "wasi"), not(feature = "wasm")))]
fn browser_panic_frames() -> String {
    CALL_STACK.with(|s| {
        let Ok(b) = s.try_borrow() else {
            return String::new();
        };
        if b.is_empty() {
            return "  (no loft frame — the panic is outside any loft call)\n".to_string();
        }
        let mut out = String::new();
        for (nm, f, ln) in b.iter().rev().take(12) {
            out.push_str(&format!("  in {nm}() ({f}:{ln})\n"));
        }
        if b.len() > 12 {
            out.push_str(&format!("  … ({} more frames)\n", b.len() - 12));
        }
        out
    })
}

// Thread-local shadow call stack used by native-compiled loft code.
// Each entry is (function_name, source_file, line_number).
// Generated code calls `cr_call_push` / `cr_call_pop` around every function body.
thread_local! {
    static CALL_STACK: RefCell<Vec<(&'static str, &'static str, u32)>> = const { RefCell::new(Vec::new()) };
}

/// The loft frames this native thread is inside, innermost first.
///
/// The `--native` counterpart of the interpreter's `State::current_call_chain`, in the
/// same shape (bare function names) so that one renderer serves both backends —
/// `RuntimeError::report_and_exit` attaches these to a fault raised by `assert` or
/// `panic`, neither of which can see a `State` to read frames from.
///
/// `try_borrow` rather than `borrow`, for the reason `browser_panic_frames` gives: a
/// fault must not turn into a second fault over its own frame list.  Missing frames are
/// worth strictly less than the message, so they yield.
#[must_use]
pub fn native_call_chain() -> Vec<String> {
    CALL_STACK.with(|s| {
        s.try_borrow().map_or_else(
            |_| Vec::new(),
            |b| b.iter().rev().map(|(nm, _, _)| (*nm).to_string()).collect(),
        )
    })
}

/// Push a frame onto the shadow call stack.  Called at the start of every
/// generated function body.  The `&'static str` arguments are string literals
/// embedded in the generated Rust code.
#[inline]
pub fn cr_call_push(name: &'static str, file: &'static str, line: u32) {
    // @PLN28 — native call-depth guard.  Generated Rust recurses one native
    // frame per loft call, so unbounded recursion overflows the OS stack with
    // an opaque `fatal runtime error: stack overflow, aborting`.  The
    // interpreter caps recursion at `State::MAX_CALL_DEPTH` and renders a typed
    // `StackOverflow`; mirror that here so both backends agree and native emits
    // a clean, source-located error instead of an abort.  (The generated `main`
    // runs on a large-stack thread — see `NATIVE_MAIN_STACK` — so this depth
    // limit is what actually fires, well before the OS stack is exhausted.)
    //
    // loft#1058 — the check comes BEFORE the push, as `State::fn_call`'s does: a
    // refused call never runs, so its frame is not part of the stack the diagnostic
    // reports.  Pushing first and tripping after put the refused callee on top of the
    // chain and made it one frame longer than the interpreter's — the two backends
    // named different functions for one fault.  The position is read off the frame
    // BELOW for the same reason: it is the function that is running.
    let overflow = CALL_STACK.with(|s| {
        let mut b = s.borrow_mut();
        if b.len() >= crate::state::State::MAX_CALL_DEPTH as usize {
            return Some(b.last().map_or((file, line), |(_, f, ln)| (*f, *ln)));
        }
        b.push((name, file, line));
        None
    });
    if let Some((running_file, running_line)) = overflow {
        cr_stack_overflow(running_file, running_line);
    }
    // @PLAN49 T1 — refresh the shared breadcrumb at every native fn
    // entry so a watchdog-fired hard-kill identifies the most recent
    // loft fn we entered.  Single combined call.  When the timeout
    // is not armed, the body is just one relaxed atomic load + branch
    // (no allocation, no mutex) — ~1-2 ns per fn entry.
    crate::timeout::checkpoint_fn("run-native", name, file, line);
}

/// Native stack size for the generated `main` thread.  The OS main-thread
/// stack (~8 MiB) overflows at a few thousand recursive loft calls — below the
/// `MAX_CALL_DEPTH` (10 000) guard.  A generous, virtual (lazily-committed)
/// stack holds 10 000 frames even for stack-heavy functions (~50 KiB/frame
/// budget), so the depth guard fires cleanly before the OS stack is exhausted.
pub const NATIVE_MAIN_STACK: usize = 512 * 1024 * 1024;

/// Report the call-stack overflow and stop the program, through the renderer every
/// other halting fault uses.  `#[cold]` / `inline(never)` keeps it off the hot
/// call-entry path.
///
/// `file` / `line` are the string literals `cr_call_push` was emitted with — the
/// declaration of the function whose entry exceeded the cap, which is the position the
/// interpreter reports for the same fault (loft#1058).  Before this the two backends
/// spelled one event two ways: no `-->` block or caret here, its own frame format, and
/// the depth count only on this side.  The count now lives in
/// `RuntimeErrorKind::describe()`, so BOTH backends carry it, and the frames come from
/// the same `render_call_chain` the interpreter's go through.
///
/// The lazy-driver bypass @PLN133 S8 asks for is `report_and_exit`'s, shared with
/// `panic` and `assert`: a fault inside a driver unwinds into `store_lazy_error` rather
/// than halting the program.
#[cold]
#[inline(never)]
fn cr_stack_overflow(file: &str, line: u32) -> ! {
    crate::runtime_error::RuntimeError::stack_overflow(file.to_string(), line).report_and_exit()
}

/// Pop a frame from the shadow call stack.  Called at the end of every
/// generated function body (including early returns via a drop guard).
#[inline]
pub fn cr_call_pop() {
    CALL_STACK.with(|s| s.borrow_mut().pop());
}

/// RAII guard that pops the shadow call stack on drop, ensuring the stack
/// stays balanced even when the function returns early.
pub struct CallGuard;

impl Drop for CallGuard {
    fn drop(&mut self) {
        cr_call_pop();
    }
}

// The return buffers a fn-ref dispatch arm allocated and the callee DELIVERED through,
// innermost frame last.  The `--native` half of the interpreter's `State::fnref_bufs`
// (`formal/closures.md`, loft#1183): a fn-ref call site is the only owner its heap return
// buffer will ever have, because the destination's static type may say it owns nothing, so
// the store is owned by the frame that holds it and travels up with the return value.
//
// A frame's own buffers are the entries above the mark [`FnRefBufGuard`] took at entry —
// a watermark rather than a frame number, so nothing has to agree about depth.
thread_local! {
    static FNREF_BUFS: RefCell<Vec<(DbRef, u64)>> = const { RefCell::new(Vec::new()) };
}

// The length of `FNREF_BUFS`, mirrored so a frame can take its mark and test it against
// the list without borrowing one: a program that never delivers a fn-ref return buffer —
// which is nearly every program, on nearly every call — pays two `Cell` reads.
thread_local! {
    static FNREF_LEN: Cell<u32> = const { Cell::new(0) };
}

/// Record what a fn-ref dispatch arm's return buffer became, once the call has answered.
///
/// The callee either DELIVERED through the buffer — the returned store IS the buffer, and
/// it now needs an owner — or handed back some other store, leaving the buffer unused and
/// this call site the only thing that can release it.  Which of the two happened is a
/// run-time fact, exactly as `State::fn_return` reads it (loft#1179): compare the stores.
///
/// The delivered one is remembered against the frame that is running, and
/// [`FnRefBufGuard`] releases it when that frame ends.
pub fn cr_fnref_buf(cell: &std::cell::UnsafeCell<Stores>, returned: DbRef, buf: DbRef) {
    if returned.store_nr != buf.store_nr {
        OpFreeRef(cell, buf, "__vc_hbuf");
        return;
    }
    let serial = {
        let stores: &mut Stores = unsafe { &mut *cell.get() };
        stores
            .allocations
            .get(buf.store_nr as usize)
            .map_or(0, |s| s.alloc_serial)
    };
    FNREF_BUFS.with(|b| {
        let mut list = b.borrow_mut();
        list.push((buf, serial));
        FNREF_LEN.with(|n| n.set(u32::try_from(list.len()).unwrap_or(u32::MAX)));
    });
}

/// The allocation counter, for a fn-ref call site to snapshot before it dispatches.
///
/// Paired with [`cr_fnref_minted`], this is the `--native` half of the question
/// `State::release_fnref_bufs` asks: was the store that came back MINTED inside the call, or
/// was it already there?  Slot numbers are reused, so nothing else can answer it.
#[must_use]
pub fn cr_alloc_serial(cell: &std::cell::UnsafeCell<Stores>) -> u64 {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    stores.stores_allocated
}

/// Give an owner to a store a fn-ref callee MINTED and handed back.
///
/// The callee does not free what it returns, and the caller may be a forwarding function whose
/// return type says nothing about it — so without this the store is owned by nobody
/// (loft#1185).  A store whose stamp is at or below `since` was already there when the call
/// began: a capture, or an argument, belonging to a frame further up and not ours to place.
///
/// Registered against the running frame, so [`FnRefBufGuard`] releases it exactly as it
/// releases a delivered return buffer.
pub fn cr_fnref_minted(
    cell: &std::cell::UnsafeCell<Stores>,
    returned: DbRef,
    since: u64,
    closure: DbRef,
) {
    if returned.store_nr == u16::MAX || returned.rec == 0 {
        return;
    }
    // The closure RECORD is never this call's mint, whatever the stamps say: it belongs to
    // whoever built the closure, and a capture read out of it answers a `DbRef` into that same
    // store.  Registering it hands the caller's own record to this frame's release — `1181`
    // reported twelve use-after-free reads of `__closure_4`, all "killed by the free of
    // `var_r`", on `--native` alone.
    if closure.store_nr != u16::MAX && returned.store_nr == closure.store_nr {
        return;
    }
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let Some(slot) = stores.allocations.get(returned.store_nr as usize) else {
        return;
    };
    if slot.free || slot.alloc_serial <= since {
        return;
    }
    let serial = slot.alloc_serial;
    FNREF_BUFS.with(|b| {
        let mut list = b.borrow_mut();
        if list.iter().any(|(d, _)| d.store_nr == returned.store_nr) {
            return;
        }
        list.push((returned, serial));
        FNREF_LEN.with(|n| n.set(u32::try_from(list.len()).unwrap_or(u32::MAX)));
    });
}

/// Releases the fn-ref return buffers a frame delivered into, when that frame ends.
///
/// The `--native` counterpart of `State::release_fnref_bufs`, and it answers the same
/// question one step coarser.  The interpreter compares the store that came back against
/// each buffer and hands only THAT one up; here the returned value is not visible at drop
/// time, so the test is the function's declared return TYPE — a frame that can hand a heap
/// value back leaves its buffers to its caller, and every other frame releases them.
///
/// Both directions of that difference are safe.  A buffer handed up is freed by an
/// ancestor rather than here, never before the value can be read; and the chain always
/// terminates, because every instrumented frame carries this guard and `main` returns
/// `void`.  What it costs is watermark: a heap-returning frame that delivers through a
/// fn-ref many times holds every one of those buffers until its caller ends, where the
/// interpreter would have released all but the one it returned.
///
/// A store the frame already released itself leaves a stale handle here; [`OpFreeRef`]
/// skips a freed slot, so the hand-up cannot turn into a double free.
pub struct FnRefBufGuard {
    cell: *const std::cell::UnsafeCell<Stores>,
    mark: u32,
    hands_up: bool,
}

impl FnRefBufGuard {
    /// Arm the guard for the frame now entering.  `hands_up` is whether this function's
    /// declared return type is a heap value, which is the only way a buffer it delivered
    /// into can still be reachable after it ends.
    #[must_use]
    pub fn new(cell: &std::cell::UnsafeCell<Stores>, hands_up: bool) -> Self {
        Self {
            cell: std::ptr::from_ref(cell),
            mark: FNREF_LEN.with(Cell::get),
            hands_up,
        }
    }
}

impl Drop for FnRefBufGuard {
    fn drop(&mut self) {
        if self.hands_up || FNREF_LEN.with(Cell::get) == self.mark {
            return;
        }
        let mine: Vec<(DbRef, u64)> = FNREF_BUFS.with(|b| {
            let mut list = b.borrow_mut();
            let from = usize::try_from(self.mark)
                .unwrap_or(usize::MAX)
                .min(list.len());
            let mine = list.split_off(from);
            FNREF_LEN.with(|n| n.set(u32::try_from(list.len()).unwrap_or(u32::MAX)));
            mine
        });
        // SAFETY: the pointer is the `cell` argument of the frame this guard belongs to,
        // which outlives the guard — the guard is a local of that same frame.
        let cell = unsafe { &*self.cell };
        for (buf, serial) in mine {
            // The frame may have released the store ITSELF — its static type can read the
            // value as owned — and slot numbers are reused, so a bare `store_nr` here would
            // eventually free somebody else's live store.  The serial is what makes the
            // handle name one allocation: a slot that is free, or that has since been
            // handed to a different allocation, is not the one this entry remembered.
            // `State::release_fnref_bufs` carries the same guard on the interpreter side —
            // without it, `1181` reported twelve use-after-free reads on `--native` alone.
            {
                let stores: &mut Stores = unsafe { &mut *cell.get() };
                match stores.allocations.get(buf.store_nr as usize) {
                    Some(slot) if !slot.free && slot.alloc_serial == serial => {}
                    _ => continue,
                }
            }
            OpFreeRef(cell, buf, "__vc_hbuf");
        }
    }
}

/// Native implementation of `stack_trace()`.
/// Reads the thread-local shadow call stack and builds `vector<StackFrame>`
/// using the same stores API as the interpreter implementation in `native.rs`.
pub fn n_stack_trace(cell: &std::cell::UnsafeCell<Stores>) -> DbRef {
    let stores: &mut Stores = unsafe { &mut *cell.get() };
    let snapshot: Vec<(&str, &str, u32)> = CALL_STACK.with(|s| s.borrow().clone());

    let sf_elm = stores.name("StackFrame");
    let sf_size = u32::from(stores.size(sf_elm));
    let fn_pos = u32::from(stores.position(sf_elm, "function"));
    let file_pos = u32::from(stores.position(sf_elm, "file"));
    let line_pos = u32::from(stores.position(sf_elm, "line"));
    let args_pos = u32::from(stores.position(sf_elm, "arguments"));
    let vars_pos = u32::from(stores.position(sf_elm, "variables"));
    let vec = stores.database(sf_size);
    stores.store_mut(&vec).set_u32_raw(vec.rec, vec.pos, 0);

    for (fn_name, file, line) in &snapshot {
        let elm = crate::vector::vector_append(&vec, sf_size, &mut stores.allocations);
        let fn_str = stores.store_mut(&vec).set_str(fn_name);
        stores
            .store_mut(&vec)
            .set_u32_raw(elm.rec, elm.pos + fn_pos, fn_str);
        let file_str = stores.store_mut(&vec).set_str(file);
        stores
            .store_mut(&vec)
            .set_u32_raw(elm.rec, elm.pos + file_pos, file_str);
        stores
            .store_mut(&vec)
            .set_int(elm.rec, elm.pos + line_pos, i64::from(*line));
        // Zero the arguments and variables vector fields.
        stores
            .store_mut(&vec)
            .set_u32_raw(elm.rec, elm.pos + args_pos, 0);
        stores
            .store_mut(&vec)
            .set_u32_raw(elm.rec, elm.pos + vars_pos, 0);
        crate::vector::vector_finish(&vec, &mut stores.allocations);
    }
    vec
}

// ── LoftStore construction for native codegen ───────────────────────────
// When native codegen calls `extern "C"` functions that take `LoftStore`,
// it needs to build one from `&mut Stores`.  These helpers provide that.

std::thread_local! {
    static CODEGEN_STORES: std::cell::Cell<*mut Stores> =
        const { std::cell::Cell::new(std::ptr::null_mut()) };
}

unsafe extern "C" fn _ffi_claim(ctx: loft_ffi::LoftStoreCtx, words: u32) -> u32 {
    let store_nr = ctx._opaque as usize as u16;
    CODEGEN_STORES.with(|c| {
        let stores = unsafe { &mut *c.get() };
        stores.allocations[store_nr as usize].claim(words)
    })
}

unsafe extern "C" fn _ffi_reload(
    ctx: loft_ffi::LoftStoreCtx,
    out_ptr: *mut *mut u8,
    out_size: *mut u32,
) {
    let store_nr = ctx._opaque as usize as u16;
    CODEGEN_STORES.with(|c| {
        let stores = unsafe { &*c.get() };
        let store = &stores.allocations[store_nr as usize];
        unsafe {
            *out_ptr = store.base_ptr();
            *out_size = store.capacity_words();
        }
    });
}

unsafe extern "C" fn _ffi_resize(ctx: loft_ffi::LoftStoreCtx, rec: u32, words: u32) -> u32 {
    let store_nr = ctx._opaque as usize as u16;
    CODEGEN_STORES.with(|c| {
        let stores = unsafe { &mut *c.get() };
        stores.allocations[store_nr as usize].resize(rec, words)
    })
}

/// @PLN24 arc G — `c_library_available`, for generated Rust.
///
/// The body of the `c_library_available` declaration in `default/02_files.loft`
/// calls THIS rather than `c_call` directly, because a `#rust` body is emitted
/// into every program that calls it while `c_call` exists only under the
/// `native-extensions` feature. Without that feature loft cannot `dlopen`
/// anything, so no C library is available and false is not a stub answer — it
/// is the true one.
#[must_use]
pub fn c_library_available(name: &str, libs: &[(&str, &str)], syms: &[(&str, &[&str])]) -> bool {
    #[cfg(feature = "native-extensions")]
    {
        crate::c_call::library_available_native(name, libs, syms)
    }
    #[cfg(not(feature = "native-extensions"))]
    {
        let _ = (name, libs, syms);
        false
    }
}

/// Build a `LoftStore` handle for calling `extern "C"` native functions that
/// need store access.  Sets a thread-local pointer so the FFI callbacks can
/// reach back into the stores.
pub fn make_loft_store(stores: &mut Stores, store_nr: u16) -> loft_ffi::LoftStore {
    CODEGEN_STORES.with(|c| c.set(std::ptr::from_mut::<Stores>(stores)));
    let store = &stores.allocations[store_nr as usize];
    loft_ffi::LoftStore {
        ptr: store.base_ptr(),
        size: store.capacity_words(),
        ctx: loft_ffi::LoftStoreCtx {
            _opaque: store_nr as usize as *mut (),
        },
        claim_fn: Some(_ffi_claim),
        reload_fn: Some(_ffi_reload),
        resize_fn: Some(_ffi_resize),
    }
}
